/* ---------------- 인터랙션 모듈 ---------------- */
Object.assign(X, {
  /* 3D 체험 페이지(embed/*.html)를 체험 영역에 그대로 끼워 넣고, 아래에 안내 문구를 보여줘요 */
  embed(st, bar, c) {
    const g = c.guide || [];
    st.innerHTML = `<div class="embw" style="width:100%;flex:1;min-height:min(560px,64vh);border-radius:20px;overflow:hidden;background:#FEFEFE;box-shadow:0 0 0 2px #1C1C20"><iframe title="${c.t} 체험" allow="autoplay" style="display:block;width:100%;height:100%;min-height:min(560px,64vh);border:0"></iframe></div>${g[0] ? `<div class="say">${g[0]}</div>` : ''}${g[1] ? `<p class="hint">${g[1]}</p>` : ''}`;
    $('iframe', st).srcdoc = EMB[c.src];
    bar.style.display = 'none';
  },
});

/* ---------------- 3D 체험 원본 (파일 경로 문제가 없도록 이 파일 안에 넣어 두었어요) ---------------- */
const EMB = {"Mallang.html": "<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n    <title>A2Z 말랑이 & 왁뿌볼 3D 체험관</title>\n    <!-- SUIT Variable Font -->\n    <link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/gh/sun-typeface/SUIT@2/fonts/variable/woff2/SUIT-Variable.css\">\n    <!-- Tailwind CSS -->\n    <script src=\"https://cdn.tailwindcss.com\"><\/script>\n    <!-- Three.js r128 -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"><\/script>\n    <!-- FontAwesome Icons -->\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n    \n    <style>\n        :root {\n            --ink: #1C1C20;\n            --paper: #FEFEFE;\n            --g1: #E1E5EA;\n            --blue: #1C94F5;\n            --r-pill: 38px;\n        }\n\n        * {\n            font-family: 'SUIT Variable', -apple-system, BlinkMacSystemFont, system-ui, sans-serif;\n            user-select: none;\n            -webkit-user-select: none;\n            touch-action: none;\n        }\n\n        body {\n            background-color: var(--paper);\n            color: var(--ink);\n            overflow: hidden;\n            width: 100vw;\n            height: 100vh;\n            margin: 0;\n        }\n\n        .a2z-btn {\n            background-color: var(--paper);\n            color: var(--ink);\n            border: 2px solid var(--ink);\n            border-radius: var(--r-pill);\n            font-weight: 800;\n            transition: all 0.15s ease;\n        }\n\n        .a2z-btn:hover {\n            background-color: var(--g1);\n        }\n\n        .a2z-btn.active {\n            background-color: var(--ink);\n            color: var(--paper);\n        }\n\n        #webgl-canvas {\n            width: 100vw;\n            height: 100vh;\n            display: block;\n            cursor: grab;\n        }\n\n        #webgl-canvas:active {\n            cursor: grabbing;\n        }\n    </style>\n</head>\n<body class=\"relative\">\n\n    <!-- 3D WebGL Canvas -->\n    <canvas id=\"webgl-canvas\"></canvas>\n\n    <!-- 상단 제어 바 -->\n    <div class=\"absolute top-6 left-0 right-0 z-20 flex flex-col items-center gap-3.5 px-4 pointer-events-none\">\n        <!-- 메인 탭 -->\n        <div class=\"pointer-events-auto flex bg-[#FEFEFE] border-2 border-[#1C1C20] rounded-full p-1\">\n            <button id=\"tab-mallang\" onclick=\"switchTab('mallang')\" class=\"a2z-btn active px-7 py-2.5 text-sm md:text-base\">\n                말랑이\n            </button>\n            <button id=\"tab-wax\" onclick=\"switchTab('wax')\" class=\"a2z-btn px-7 py-2.5 text-sm md:text-base border-transparent hover:border-[#1C1C20]\">\n                왁뿌볼\n            </button>\n        </div>\n\n        <!-- 서브 탭 (말랑이 선택) -->\n        <div id=\"mallang-selector\" class=\"pointer-events-auto flex flex-wrap justify-center gap-2\">\n            <button onclick=\"selectMallang('butter')\" id=\"btn-butter\" class=\"a2z-btn active px-4 py-1.5 text-xs md:text-sm\">\n                버터바 크런치\n            </button>\n            <button onclick=\"selectMallang('watermelon')\" id=\"btn-watermelon\" class=\"a2z-btn px-4 py-1.5 text-xs md:text-sm\">\n                수박 샤베트\n            </button>\n            <button onclick=\"selectMallang('cheese')\" id=\"btn-cheese\" class=\"a2z-btn px-4 py-1.5 text-xs md:text-sm\">\n                치즈\n            </button>\n        </div>\n    </div>\n\n    <!-- 왁뿌볼 3단계 미니 게이지 프로그레스 바 -->\n    <div id=\"wax-bar-container\" class=\"hidden absolute bottom-12 left-1/2 -translate-x-1/2 z-20 pointer-events-none\">\n        <div class=\"w-56 h-4 bg-[#E1E5EA] border-2 border-[#1C1C20] rounded-full overflow-hidden p-0.5 shadow-sm\">\n            <div id=\"crack-bar\" class=\"bg-[#1C94F5] h-full rounded-full transition-all duration-300\" style=\"width: 0%\"></div>\n        </div>\n    </div>\n\n    <!-- 우측 하단 버튼 -->\n    <div class=\"absolute bottom-6 right-6 z-20 flex gap-3\">\n        <button id=\"btn-reset\" onclick=\"rewrapWax()\" title=\"다시 씌우기\" class=\"hidden w-12 h-12 rounded-full border-2 border-[#1C1C20] bg-[#FEFEFE] text-[#1C1C20] flex items-center justify-center hover:bg-[#1C1C20] hover:text-white transition-all\">\n            <i class=\"fa-solid fa-rotate-left text-lg\"></i>\n        </button>\n        <button id=\"btn-sound\" onclick=\"toggleSound()\" title=\"음향 설정\" class=\"w-12 h-12 rounded-full border-2 border-[#1C1C20] bg-[#FEFEFE] text-[#1C1C20] flex items-center justify-center hover:bg-[#1C1C20] hover:text-white transition-all\">\n            <i id=\"sound-icon\" class=\"fa-solid fa-volume-high text-lg\"></i>\n        </button>\n    </div>\n\n    <script>\n        /* =========================================================================\n           1. 찰진 고주파 습식 흡착 오디오 엔진 ('둥둥' 저음 100% 제거)\n           ========================================================================= */\n        class RealSoundEngine {\n            constructor() {\n                this.ctx = null;\n                this.enabled = true;\n                this.isCheesePlaying = false;\n                this.lastCheeseTime = 0;\n                this.lastCrunchTime = 0;\n                this.sorbetGain = null;\n                this.sorbetFilter = null;\n                this.sorbetSource = null;\n                this.isSorbetRunning = false;\n            }\n\n            init() {\n                if (!this.ctx) {\n                    const AudioContext = window.AudioContext || window.webkitAudioContext;\n                    this.ctx = new AudioContext();\n                }\n                if (this.ctx.state === 'suspended') {\n                    this.ctx.resume();\n                }\n            }\n\n            // 치즈 & 연두색 속 알맹이: 둥둥거리는 저음 전면 차단 -> 리얼 '쮹-' 찰진 습식 마찰음\n            playStickySquishSound() {\n                if (!this.enabled) return;\n                this.init();\n                const now = this.ctx.currentTime;\n\n                if (this.isCheesePlaying || (now - this.lastCheeseTime < 0.28)) return;\n                this.isCheesePlaying = true;\n                this.lastCheeseTime = now;\n\n                const noiseBuf = this.createNoiseBuffer(0.2);\n                const noiseSrc = this.ctx.createBufferSource();\n                \n                // 1) 350Hz 이하 저음 전면 차단 (둥둥거리는 울림 제로)\n                const highpass = this.ctx.createBiquadFilter();\n                highpass.type = 'highpass';\n                highpass.frequency.setValueAtTime(350, now);\n\n                // 2) 800Hz -> 2800Hz 상승 습식 마찰 필터 (쮹- 쫀득하게 빨리는 느낌)\n                const bandpass = this.ctx.createBiquadFilter();\n                bandpass.type = 'bandpass';\n                bandpass.frequency.setValueAtTime(800, now);\n                bandpass.frequency.exponentialRampToValueAtTime(2800, now + 0.12);\n                bandpass.frequency.exponentialRampToValueAtTime(1000, now + 0.19);\n                bandpass.Q.setValueAtTime(3.2, now);\n\n                const gain = this.ctx.createGain();\n                gain.gain.setValueAtTime(0.35, now);\n                gain.gain.exponentialRampToValueAtTime(0.001, now + 0.19);\n\n                noiseSrc.buffer = noiseBuf;\n                noiseSrc.connect(highpass);\n                highpass.connect(bandpass);\n                bandpass.connect(gain);\n                gain.connect(this.ctx.destination);\n\n                noiseSrc.start(now);\n                noiseSrc.stop(now + 0.2);\n\n                setTimeout(() => {\n                    this.isCheesePlaying = false;\n                }, 280);\n            }\n\n            // 버터바 크런치 사운드\n            playButterCrunch() {\n                if (!this.enabled) return;\n                this.init();\n                const now = this.ctx.currentTime;\n\n                if (now - this.lastCrunchTime < 0.25) return;\n                this.lastCrunchTime = now;\n\n                const pops = [1200, 850];\n                pops.forEach((freq, idx) => {\n                    const t = now + idx * 0.025;\n                    const osc = this.ctx.createOscillator();\n                    const gain = this.ctx.createGain();\n\n                    osc.type = 'triangle';\n                    osc.frequency.setValueAtTime(freq, t);\n                    osc.frequency.exponentialRampToValueAtTime(160, t + 0.02);\n\n                    gain.gain.setValueAtTime(0.28, t);\n                    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.022);\n\n                    osc.connect(gain);\n                    gain.connect(this.ctx.destination);\n\n                    osc.start(t);\n                    osc.stop(t + 0.025);\n                });\n            }\n\n            // 수박 샤베트 마찰음\n            initSorbetLoop() {\n                if (this.isSorbetRunning) return;\n                this.init();\n\n                const bufferSize = this.ctx.sampleRate * 2;\n                const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);\n                const data = buffer.getChannelData(0);\n                for (let i = 0; i < bufferSize; i++) {\n                    data[i] = Math.random() * 2 - 1;\n                }\n\n                this.sorbetSource = this.ctx.createBufferSource();\n                this.sorbetSource.buffer = buffer;\n                this.sorbetSource.loop = true;\n\n                this.sorbetFilter = this.ctx.createBiquadFilter();\n                this.sorbetFilter.type = 'bandpass';\n                this.sorbetFilter.frequency.setValueAtTime(1200, this.ctx.currentTime);\n                this.sorbetFilter.Q.setValueAtTime(1.8, this.ctx.currentTime);\n\n                this.sorbetGain = this.ctx.createGain();\n                this.sorbetGain.gain.setValueAtTime(0, this.ctx.currentTime);\n\n                this.sorbetSource.connect(this.sorbetFilter);\n                this.sorbetFilter.connect(this.sorbetGain);\n                this.sorbetGain.connect(this.ctx.destination);\n\n                this.sorbetSource.start();\n                this.isSorbetRunning = true;\n            }\n\n            updateSorbetDrag(speed) {\n                if (!this.enabled) return;\n                this.initSorbetLoop();\n                if (!this.sorbetGain) return;\n\n                const now = this.ctx.currentTime;\n                const targetGain = Math.min(speed * 1.5, 0.32);\n                const targetFreq = 850 + Math.min(speed * 1800, 1600);\n\n                this.sorbetGain.gain.setTargetAtTime(targetGain, now, 0.03);\n                this.sorbetFilter.frequency.setTargetAtTime(targetFreq, now, 0.04);\n            }\n\n            stopSorbetDrag() {\n                if (this.sorbetGain && this.ctx) {\n                    this.sorbetGain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.08);\n                }\n            }\n\n            // 왁스 파쇄 스냅 사운드\n            playWaxCrackSnap() {\n                if (!this.enabled) return;\n                this.init();\n                const now = this.ctx.currentTime;\n\n                const noiseBuf = this.createNoiseBuffer(0.08);\n                const noiseSrc = this.ctx.createBufferSource();\n                const filter = this.ctx.createBiquadFilter();\n                const gain = this.ctx.createGain();\n\n                noiseSrc.buffer = noiseBuf;\n                filter.type = 'highpass';\n                filter.frequency.setValueAtTime(1800, now);\n\n                gain.gain.setValueAtTime(0.45, now);\n                gain.gain.exponentialRampToValueAtTime(0.001, now + 0.075);\n\n                noiseSrc.connect(filter);\n                filter.connect(gain);\n                gain.connect(this.ctx.destination);\n\n                noiseSrc.start(now);\n                noiseSrc.stop(now + 0.08);\n            }\n\n            playWaxShatter() {\n                if (!this.enabled) return;\n                this.init();\n                for (let i = 0; i < 3; i++) {\n                    setTimeout(() => this.playWaxCrackSnap(), i * 35);\n                }\n            }\n\n            createNoiseBuffer(duration) {\n                const bufferSize = this.ctx.sampleRate * duration;\n                const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);\n                const data = buffer.getChannelData(0);\n                for (let i = 0; i < bufferSize; i++) {\n                    data[i] = Math.random() * 2 - 1;\n                }\n                return buffer;\n            }\n        }\n\n        const soundEngine = new RealSoundEngine();\n\n        /* =========================================================================\n           2. THREE.JS 3D Scene Setup\n           ========================================================================= */\n        let scene, camera, renderer, currentMeshGroup, mainMesh;\n        let activeTab = 'mallang';\n        let currentMallangType = 'butter';\n\n        let originalPositions = null;\n        let velocities = null;\n        let activeGeometry = null;\n\n        let isPointerDown = false;\n        let pointerButton = 0;\n        let isDragging = false;\n        let grabbedVertexIndex = -1;\n        let grabPlane = new THREE.Plane();\n        let raycaster = new THREE.Raycaster();\n        let mouse = new THREE.Vector2();\n        let previousMousePosition = { x: 0, y: 0 };\n        let pullTarget = new THREE.Vector3();\n\n        let waxShellMesh = null;\n        let waxCracksCanvas = null;\n        let waxCracksTexture = null;\n        let waxCrackContext = null;\n        let waxCrackCount = 0;\n        let isWaxShattered = false;\n        let waxHoldTimer = null;\n        let waxParticlesGroup = null;\n        let currentTouchUV = null;\n\n        function init3D() {\n            const canvas = document.getElementById('webgl-canvas');\n\n            scene = new THREE.Scene();\n            scene.background = new THREE.Color(0xfefeef);\n\n            camera = new THREE.PerspectiveCamera(38, window.innerWidth / window.innerHeight, 0.1, 100);\n            camera.position.set(0, 3.2, 4.8);\n            camera.lookAt(0, -0.1, 0);\n\n            renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: false });\n            renderer.setSize(window.innerWidth, window.innerHeight);\n            renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n            renderer.shadowMap.enabled = true;\n            renderer.shadowMap.type = THREE.PCFSoftShadowMap;\n\n            const ambientLight = new THREE.AmbientLight(0xffffff, 0.88);\n            scene.add(ambientLight);\n\n            const dirLight = new THREE.DirectionalLight(0xffffff, 0.65);\n            dirLight.position.set(3, 7, 4);\n            dirLight.castShadow = true;\n            scene.add(dirLight);\n\n            currentMeshGroup = new THREE.Group();\n            scene.add(currentMeshGroup);\n\n            buildButterMallang();\n            setupEventListeners();\n            animate();\n        }\n\n        function setupPhysicsBuffers(geometry) {\n            activeGeometry = geometry;\n            const posAttr = geometry.attributes.position;\n            const count = posAttr.count;\n\n            originalPositions = new Float32Array(count * 3);\n            velocities = new Float32Array(count * 3);\n\n            for (let i = 0; i < count * 3; i++) {\n                originalPositions[i] = posAttr.array[i];\n                velocities[i] = 0;\n            }\n        }\n\n        function clearCurrentGroup() {\n            while (currentMeshGroup.children.length > 0) {\n                const obj = currentMeshGroup.children[0];\n                if (obj.geometry) obj.geometry.dispose();\n                if (obj.material) {\n                    if (Array.isArray(obj.material)) obj.material.forEach(m => m.dispose());\n                    else obj.material.dispose();\n                }\n                currentMeshGroup.remove(obj);\n            }\n            waxShellMesh = null;\n            if (waxParticlesGroup) {\n                scene.remove(waxParticlesGroup);\n                waxParticlesGroup = null;\n            }\n            currentMeshGroup.rotation.set(0, 0, 0);\n            currentMeshGroup.position.set(0, 0, 0);\n            currentMeshGroup.scale.set(1, 1, 1);\n        }\n\n        function buildButterMallang() {\n            clearCurrentGroup();\n\n            const labelCanvas = document.createElement('canvas');\n            labelCanvas.width = 512;\n            labelCanvas.height = 256;\n            const ctx = labelCanvas.getContext('2d');\n\n            ctx.fillStyle = '#f4d15d';\n            ctx.fillRect(0, 0, 512, 256);\n            ctx.textAlign = 'center';\n            ctx.fillStyle = '#0e3a62';\n            ctx.font = 'bold 32px sans-serif';\n            ctx.fillText('4oz. NET WT.(113g)', 256, 70);\n            ctx.font = '900 86px sans-serif';\n            ctx.fillText('BUTTER', 256, 160);\n            ctx.font = 'bold 30px sans-serif';\n            ctx.fillText('SALTED', 256, 215);\n\n            const butterTexture = new THREE.CanvasTexture(labelCanvas);\n            const geometry = new THREE.BoxGeometry(2.4, 0.85, 0.95, 32, 16, 16);\n\n            const sideMaterial = new THREE.MeshPhysicalMaterial({ color: 0xf5d461, roughness: 0.35, clearcoat: 0.3 });\n            const topMaterial = new THREE.MeshPhysicalMaterial({ map: butterTexture, color: 0xf5d461, roughness: 0.35, clearcoat: 0.3 });\n\n            mainMesh = new THREE.Mesh(geometry, [sideMaterial, sideMaterial, topMaterial, sideMaterial, sideMaterial, sideMaterial]);\n            mainMesh.castShadow = true;\n            currentMeshGroup.add(mainMesh);\n\n            setupPhysicsBuffers(geometry);\n        }\n\n        function buildWatermelonMallang() {\n            clearCurrentGroup();\n\n            const seedCanvas = document.createElement('canvas');\n            seedCanvas.width = 512;\n            seedCanvas.height = 256;\n            const ctx = seedCanvas.getContext('2d');\n\n            ctx.fillStyle = '#ff2040';\n            ctx.fillRect(0, 0, 512, 256);\n            ctx.fillStyle = '#111111';\n            for (let i = 0; i < 55; i++) {\n                const x = Math.random() * 512;\n                const y = Math.random() * 256;\n                ctx.beginPath();\n                ctx.ellipse(x, y, 4, 7, Math.random() * Math.PI, 0, Math.PI * 2);\n                ctx.fill();\n            }\n\n            const seedTexture = new THREE.CanvasTexture(seedCanvas);\n            const geometry = new THREE.SphereGeometry(0.7, 40, 40);\n\n            const material = new THREE.MeshPhysicalMaterial({\n                map: seedTexture,\n                color: 0xff2e4c,\n                roughness: 0.25,\n                transmission: 0.2,\n                clearcoat: 0.6\n            });\n\n            mainMesh = new THREE.Mesh(geometry, material);\n            mainMesh.castShadow = true;\n            currentMeshGroup.add(mainMesh);\n\n            setupPhysicsBuffers(geometry);\n        }\n\n        function buildCheeseMallang() {\n            clearCurrentGroup();\n\n            const geometry = new THREE.BoxGeometry(1.3, 1.3, 1.3, 32, 32, 32);\n            const pos = geometry.attributes.position;\n            const pitCenters = [\n                new THREE.Vector3(0.4, 0.3, 0.65),\n                new THREE.Vector3(-0.35, -0.25, 0.65),\n                new THREE.Vector3(0.65, -0.2, 0.3),\n                new THREE.Vector3(-0.65, 0.25, -0.2)\n            ];\n\n            for (let i = 0; i < pos.count; i++) {\n                let v = new THREE.Vector3(pos.getX(i), pos.getY(i), pos.getZ(i));\n                for (let k = 0; k < pitCenters.length; k++) {\n                    const center = pitCenters[k];\n                    const dist = v.distanceTo(center);\n                    if (dist < 0.32) {\n                        const depth = Math.pow(1 - dist / 0.32, 2) * 0.22;\n                        v.addScaledVector(center.clone().negate().normalize(), depth);\n                    }\n                }\n                pos.setXYZ(i, v.x, v.y, v.z);\n            }\n            geometry.computeVertexNormals();\n\n            const material = new THREE.MeshStandardMaterial({ color: 0xffeaa7, roughness: 0.35 });\n            mainMesh = new THREE.Mesh(geometry, material);\n            mainMesh.castShadow = true;\n            currentMeshGroup.add(mainMesh);\n\n            setupPhysicsBuffers(geometry);\n        }\n\n        function buildWaxBall() {\n            clearCurrentGroup();\n            waxCrackCount = 0;\n            isWaxShattered = false;\n            currentTouchUV = null;\n            updateWaxHUD();\n\n            // 속 알맹이: 연두색 (0x82cd47)\n            const innerGeo = new THREE.SphereGeometry(1.05, 40, 40);\n            const innerMat = new THREE.MeshPhysicalMaterial({\n                color: 0x82cd47,\n                roughness: 0.25,\n                transmission: 0.2,\n                clearcoat: 0.8\n            });\n            mainMesh = new THREE.Mesh(innerGeo, innerMat);\n            mainMesh.castShadow = true;\n            currentMeshGroup.add(mainMesh);\n\n            // 외부 아이보리 왁스 껍질\n            waxCracksCanvas = document.createElement('canvas');\n            waxCracksCanvas.width = 512;\n            waxCracksCanvas.height = 512;\n            waxCrackContext = waxCracksCanvas.getContext('2d');\n\n            waxCrackContext.fillStyle = '#f7f1e3';\n            waxCrackContext.fillRect(0, 0, 512, 512);\n\n            waxCracksTexture = new THREE.CanvasTexture(waxCracksCanvas);\n\n            const waxGeo = new THREE.SphereGeometry(1.12, 40, 40);\n            const waxMat = new THREE.MeshStandardMaterial({\n                map: waxCracksTexture,\n                roughness: 0.7,\n                bumpMap: waxCracksTexture,\n                bumpScale: 0.03\n            });\n\n            waxShellMesh = new THREE.Mesh(waxGeo, waxMat);\n            waxShellMesh.castShadow = true;\n            currentMeshGroup.add(waxShellMesh);\n\n            setupPhysicsBuffers(innerGeo);\n        }\n\n        function drawLightningCrackAtHit(step, uv) {\n            if (!waxCrackContext) return;\n\n            let curX = 256;\n            let curY = 220;\n\n            if (uv) {\n                curX = uv.x * 512;\n                curY = (1 - uv.y) * 512;\n            }\n\n            if (step === 2) {\n                curX += (Math.random() - 0.5) * 70;\n                curY += (Math.random() - 0.5) * 70;\n            } else if (step === 3) {\n                curX += (Math.random() - 0.5) * 110;\n                curY += (Math.random() - 0.5) * 110;\n            }\n\n            waxCrackContext.strokeStyle = '#1c1c20';\n            waxCrackContext.lineWidth = 6;\n            waxCrackContext.lineCap = 'round';\n            waxCrackContext.lineJoin = 'miter';\n\n            waxCrackContext.beginPath();\n            waxCrackContext.moveTo(curX, curY);\n\n            const segments = 4;\n            let angle = Math.random() * Math.PI * 2;\n\n            for (let i = 0; i < segments; i++) {\n                angle += (i % 2 === 0 ? 0.85 : -0.85);\n                const len = 42 + Math.random() * 25;\n                curX += Math.cos(angle) * len;\n                curY += Math.sin(angle) * len;\n                waxCrackContext.lineTo(curX, curY);\n            }\n            waxCrackContext.stroke();\n\n            waxCracksTexture.needsUpdate = true;\n            soundEngine.playWaxCrackSnap();\n        }\n\n        function processWaxSqueezeStep() {\n            if (isWaxShattered || activeTab !== 'wax') return;\n\n            if (waxCrackCount < 3) {\n                waxCrackCount++;\n                updateWaxHUD();\n                drawLightningCrackAtHit(waxCrackCount, currentTouchUV);\n            } else if (waxCrackCount >= 3) {\n                shatterWaxShell();\n            }\n        }\n\n        function shatterWaxShell() {\n            if (isWaxShattered) return;\n            isWaxShattered = true;\n\n            soundEngine.playWaxShatter();\n\n            if (waxShellMesh) {\n                waxShellMesh.visible = false;\n            }\n\n            waxParticlesGroup = new THREE.Group();\n            scene.add(waxParticlesGroup);\n\n            const shardGeo = new THREE.ConeGeometry(0.12, 0.2, 3);\n            const shardMat = new THREE.MeshStandardMaterial({ color: 0xf7f1e3, roughness: 0.8 });\n\n            for (let i = 0; i < 28; i++) {\n                const shard = new THREE.Mesh(shardGeo, shardMat);\n                shard.position.copy(currentMeshGroup.position);\n\n                const vel = new THREE.Vector3(\n                    (Math.random() - 0.5) * 0.18,\n                    Math.random() * 0.18 + 0.05,\n                    (Math.random() - 0.5) * 0.18\n                );\n\n                shard.userData = {\n                    velocity: vel,\n                    rotSpeed: new THREE.Vector3(Math.random() * 0.2, Math.random() * 0.2, Math.random() * 0.2),\n                    life: 1.0\n                };\n                waxParticlesGroup.add(shard);\n            }\n\n            const barContainer = document.getElementById('wax-bar-container');\n            if (barContainer) barContainer.classList.add('hidden');\n        }\n\n        function rewrapWax() {\n            if (activeTab === 'wax') {\n                buildWaxBall();\n                const barContainer = document.getElementById('wax-bar-container');\n                if (barContainer) barContainer.classList.remove('hidden');\n            }\n        }\n\n        function updateWaxHUD() {\n            const bar = document.getElementById('crack-bar');\n            if (bar) {\n                const pct = Math.min((waxCrackCount / 3) * 100, 100);\n                bar.style.width = `${pct}%`;\n            }\n        }\n\n        /* =========================================================================\n           3. 터치 및 드래그 반응\n           ========================================================================= */\n        function setupEventListeners() {\n            const canvas = document.getElementById('webgl-canvas');\n            document.addEventListener('contextmenu', e => e.preventDefault());\n\n            canvas.addEventListener('pointerdown', onPointerDown);\n            canvas.addEventListener('pointermove', onPointerMove);\n            canvas.addEventListener('pointerup', onPointerUp);\n            canvas.addEventListener('pointercancel', onPointerUp);\n\n            window.addEventListener('resize', onWindowResize);\n        }\n\n        function updateMouseCoords(e) {\n            mouse.x = (e.clientX / window.innerWidth) * 2 - 1;\n            mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;\n        }\n\n        function applyPressDent(hitPoint) {\n            if (!activeGeometry || !mainMesh) return;\n\n            const localHit = mainMesh.worldToLocal(hitPoint.clone());\n            const posAttr = activeGeometry.attributes.position;\n\n            for (let i = 0; i < posAttr.count; i++) {\n                const vPos = new THREE.Vector3(posAttr.getX(i), posAttr.getY(i), posAttr.getZ(i));\n                const dist = vPos.distanceTo(localHit);\n\n                if (dist < 0.6) {\n                    const factor = Math.cos((dist / 0.6) * (Math.PI / 2));\n                    vPos.addScaledVector(localHit.clone().negate().normalize(), 0.18 * factor);\n                    posAttr.setXYZ(i, vPos.x, vPos.y, vPos.z);\n                }\n            }\n\n            posAttr.needsUpdate = true;\n            activeGeometry.computeVertexNormals();\n\n            currentMeshGroup.scale.set(1.06, 0.9, 1.06);\n\n            if (activeTab === 'wax' && isWaxShattered) {\n                soundEngine.playStickySquishSound();\n            }\n        }\n\n        function onPointerDown(e) {\n            isPointerDown = true;\n            pointerButton = e.button;\n            updateMouseCoords(e);\n\n            previousMousePosition = { x: e.clientX, y: e.clientY };\n\n            if (pointerButton === 0) {\n                raycaster.setFromCamera(mouse, camera);\n\n                const targetMesh = (waxShellMesh && waxShellMesh.visible) ? waxShellMesh : mainMesh;\n                const intersects = raycaster.intersectObject(targetMesh);\n\n                if (intersects.length > 0) {\n                    const hit = intersects[0];\n                    currentTouchUV = hit.uv;\n\n                    if (activeTab === 'wax' && !isWaxShattered) {\n                        processWaxSqueezeStep();\n                        waxHoldTimer = setInterval(() => {\n                            processWaxSqueezeStep();\n                        }, 1000);\n                        return;\n                    }\n\n                    applyPressDent(hit.point);\n                    grabbedVertexIndex = findNearestVertex(hit.point);\n\n                    if (grabbedVertexIndex !== -1) {\n                        isDragging = true;\n                        grabPlane.setFromNormalAndCoplanarPoint(\n                            camera.getWorldDirection(new THREE.Vector3()).negate(),\n                            hit.point\n                        );\n                    }\n                }\n            }\n        }\n\n        function onPointerMove(e) {\n            if (!isPointerDown) return;\n\n            const deltaX = e.clientX - previousMousePosition.x;\n            const deltaY = e.clientY - previousMousePosition.y;\n            const moveSpeed = Math.sqrt(deltaX * deltaX + deltaY * deltaY);\n\n            if (pointerButton === 2 || (isPointerDown && !isDragging)) {\n                currentMeshGroup.rotation.y += deltaX * 0.008;\n                currentMeshGroup.rotation.x += deltaY * 0.008;\n            } else if (isDragging && grabbedVertexIndex !== -1) {\n                updateMouseCoords(e);\n                raycaster.setFromCamera(mouse, camera);\n\n                if (raycaster.ray.intersectPlane(grabPlane, pullTarget)) {\n                    applyVolumePreservingStretch(pullTarget, moveSpeed);\n                }\n            }\n\n            previousMousePosition = { x: e.clientX, y: e.clientY };\n        }\n\n        function onPointerUp() {\n            isPointerDown = false;\n            isDragging = false;\n            grabbedVertexIndex = -1;\n\n            soundEngine.stopSorbetDrag();\n\n            if (waxHoldTimer) {\n                clearInterval(waxHoldTimer);\n                waxHoldTimer = null;\n            }\n        }\n\n        function findNearestVertex(worldPoint) {\n            if (!activeGeometry) return -1;\n\n            const localPoint = mainMesh.worldToLocal(worldPoint.clone());\n            const posAttr = activeGeometry.attributes.position;\n            let minDist = Infinity;\n            let nearestIdx = -1;\n\n            for (let i = 0; i < posAttr.count; i++) {\n                const dist = localPoint.distanceToSquared(\n                    new THREE.Vector3(posAttr.getX(i), posAttr.getY(i), posAttr.getZ(i))\n                );\n                if (dist < minDist) {\n                    minDist = dist;\n                    nearestIdx = i;\n                }\n            }\n            return nearestIdx;\n        }\n\n        function applyVolumePreservingStretch(targetWorldPoint, moveSpeed) {\n            if (grabbedVertexIndex === -1 || !activeGeometry) return;\n\n            const targetLocal = mainMesh.worldToLocal(targetWorldPoint.clone());\n            const posAttr = activeGeometry.attributes.position;\n\n            const grabbedOrig = new THREE.Vector3(\n                originalPositions[grabbedVertexIndex * 3],\n                originalPositions[grabbedVertexIndex * 3 + 1],\n                originalPositions[grabbedVertexIndex * 3 + 2]\n            );\n\n            const pullDir = targetLocal.clone().sub(grabbedOrig);\n            const pullMag = pullDir.length();\n            if (pullMag < 0.001) return;\n\n            const influenceRadius = 1.2;\n\n            for (let i = 0; i < posAttr.count; i++) {\n                const idx = i * 3;\n                const origPos = new THREE.Vector3(\n                    originalPositions[idx],\n                    originalPositions[idx + 1],\n                    originalPositions[idx + 2]\n                );\n\n                const dist = origPos.distanceTo(grabbedOrig);\n\n                if (dist < influenceRadius) {\n                    const factor = Math.exp(-Math.pow(dist / (influenceRadius * 0.6), 2));\n                    const finalPos = origPos.clone().add(pullDir.clone().multiplyScalar(factor * 0.55));\n                    posAttr.setXYZ(i, finalPos.x, finalPos.y, finalPos.z);\n                }\n            }\n\n            posAttr.needsUpdate = true;\n            activeGeometry.computeVertexNormals();\n\n            if (activeTab === 'wax' && isWaxShattered) {\n                soundEngine.playStickySquishSound();\n            } else if (currentMallangType === 'watermelon') {\n                soundEngine.updateSorbetDrag(moveSpeed * 0.05);\n            } else if (currentMallangType === 'cheese') {\n                soundEngine.playStickySquishSound();\n            } else if (currentMallangType === 'butter') {\n                if (pullMag > 0.08) soundEngine.playButterCrunch();\n            }\n        }\n\n        function updateVertexPhysics() {\n            if (!activeGeometry) return;\n\n            currentMeshGroup.scale.lerp(new THREE.Vector3(1, 1, 1), 0.1);\n            if (isDragging) return;\n\n            const posAttr = activeGeometry.attributes.position;\n            const count = posAttr.count;\n            const springK = 0.15;\n            const damping = 0.82;\n            let needsUpdate = false;\n\n            for (let i = 0; i < count; i++) {\n                const idx = i * 3;\n                let px = posAttr.array[idx];\n                let py = posAttr.array[idx + 1];\n                let pz = posAttr.array[idx + 2];\n\n                const ox = originalPositions[idx];\n                const oy = originalPositions[idx + 1];\n                const oz = originalPositions[idx + 2];\n\n                let vx = (velocities[idx] - springK * (px - ox)) * damping;\n                let vy = (velocities[idx + 1] - springK * (py - oy)) * damping;\n                let vz = (velocities[idx + 2] - springK * (pz - oz)) * damping;\n\n                velocities[idx] = vx;\n                velocities[idx + 1] = vy;\n                velocities[idx + 2] = vz;\n\n                posAttr.array[idx] = px + vx;\n                posAttr.array[idx + 1] = py + vy;\n                posAttr.array[idx + 2] = pz + vz;\n\n                if (Math.abs(vx) > 0.0001 || Math.abs(px - ox) > 0.0001) needsUpdate = true;\n            }\n\n            if (needsUpdate) {\n                posAttr.needsUpdate = true;\n                activeGeometry.computeVertexNormals();\n            }\n        }\n\n        function updateParticles() {\n            if (!waxParticlesGroup) return;\n\n            for (let i = waxParticlesGroup.children.length - 1; i >= 0; i--) {\n                const p = waxParticlesGroup.children[i];\n                const u = p.userData;\n\n                p.position.add(u.velocity);\n                p.rotation.x += u.rotSpeed.x;\n                p.rotation.y += u.rotSpeed.y;\n\n                u.velocity.y -= 0.006;\n                u.life -= 0.02;\n\n                p.scale.setScalar(Math.max(u.life, 0.001));\n\n                if (u.life <= 0) waxParticlesGroup.remove(p);\n            }\n        }\n\n        function animate() {\n            requestAnimationFrame(animate);\n            updateVertexPhysics();\n            updateParticles();\n            renderer.render(scene, camera);\n        }\n\n        function onWindowResize() {\n            camera.aspect = window.innerWidth / window.innerHeight;\n            camera.updateProjectionMatrix();\n            renderer.setSize(window.innerWidth, window.innerHeight);\n        }\n\n        function switchTab(tab) {\n            activeTab = tab;\n\n            const btnMallang = document.getElementById('tab-mallang');\n            const btnWax = document.getElementById('tab-wax');\n            const mallangSelector = document.getElementById('mallang-selector');\n            const waxBarContainer = document.getElementById('wax-bar-container');\n            const btnReset = document.getElementById('btn-reset');\n\n            if (tab === 'mallang') {\n                btnMallang.classList.add('active');\n                btnWax.classList.remove('active');\n\n                mallangSelector.classList.remove('hidden');\n                waxBarContainer.classList.add('hidden');\n                btnReset.classList.add('hidden');\n\n                selectMallang(currentMallangType);\n            } else {\n                btnWax.classList.add('active');\n                btnMallang.classList.remove('active');\n\n                mallangSelector.classList.add('hidden');\n\n                if (!isWaxShattered) {\n                    waxBarContainer.classList.remove('hidden');\n                }\n                btnReset.classList.remove('hidden');\n\n                buildWaxBall();\n            }\n        }\n\n        function selectMallang(type) {\n            currentMallangType = type;\n\n            ['butter', 'watermelon', 'cheese'].forEach(t => {\n                const btn = document.getElementById(`btn-${t}`);\n                if (t === type) btn.classList.add('active');\n                else btn.classList.remove('active');\n            });\n\n            if (type === 'butter') buildButterMallang();\n            else if (type === 'watermelon') buildWatermelonMallang();\n            else if (type === 'cheese') buildCheeseMallang();\n        }\n\n        function toggleSound() {\n            soundEngine.enabled = !soundEngine.enabled;\n            const soundIcon = document.getElementById('sound-icon');\n            if (soundEngine.enabled) {\n                soundIcon.className = 'fa-solid fa-volume-high text-lg';\n            } else {\n                soundIcon.className = 'fa-solid fa-volume-xmark text-lg text-red-500';\n            }\n        }\n\n        window.onload = function() {\n            init3D();\n            switchTab('mallang');\n        };\n    <\/script>\n</body>\n</html>", "Keycap.html": "<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n    <title>A2Z 키캡 & 클리커 3D 체험관</title>\n    <!-- SUIT Variable Font -->\n    <link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/gh/sun-typeface/SUIT@2/fonts/variable/woff2/SUIT-Variable.css\">\n    <!-- Tailwind CSS -->\n    <script src=\"https://cdn.tailwindcss.com\"><\/script>\n    <!-- Three.js r128 -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"><\/script>\n    <!-- FontAwesome Icons -->\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n    \n    <style>\n        :root {\n            --ink: #1C1C20;\n            --paper: #FEFEFE;\n            --g1: #E1E5EA;\n            --blue: #1C94F5;\n            --r-pill: 38px;\n        }\n\n        * {\n            font-family: 'SUIT Variable', -apple-system, BlinkMacSystemFont, system-ui, sans-serif;\n            user-select: none;\n            -webkit-user-select: none;\n            touch-action: none;\n        }\n\n        body {\n            background-color: var(--paper);\n            color: var(--ink);\n            overflow: hidden;\n            width: 100vw;\n            height: 100vh;\n            margin: 0;\n        }\n\n        .a2z-btn {\n            background-color: var(--paper);\n            color: var(--ink);\n            border: 2px solid var(--ink);\n            border-radius: var(--r-pill);\n            font-weight: 800;\n            transition: all 0.15s ease;\n        }\n\n        .a2z-btn:hover {\n            background-color: var(--g1);\n        }\n\n        .a2z-btn.active {\n            background-color: var(--ink);\n            color: var(--paper);\n        }\n\n        #webgl-canvas {\n            width: 100vw;\n            height: 100vh;\n            display: block;\n            cursor: grab;\n        }\n\n        #webgl-canvas:active {\n            cursor: grabbing;\n        }\n    </style>\n</head>\n<body class=\"relative\">\n\n    <!-- 3D WebGL Canvas -->\n    <canvas id=\"webgl-canvas\"></canvas>\n\n    <!-- 상단 제어 바 -->\n    <div class=\"absolute top-6 left-0 right-0 z-20 flex flex-col items-center gap-3.5 px-4 pointer-events-none\">\n        <!-- 메인 탭 -->\n        <div class=\"pointer-events-auto flex bg-[#FEFEFE] border-2 border-[#1C1C20] rounded-full p-1 shadow-sm\">\n            <button id=\"tab-keycap\" onclick=\"switchMainTab('keycap')\" class=\"a2z-btn active px-8 py-2.5 text-sm md:text-base\">\n                키캡\n            </button>\n            <button id=\"tab-clicker\" onclick=\"switchMainTab('clicker')\" class=\"a2z-btn px-8 py-2.5 text-sm md:text-base border-transparent hover:border-[#1C1C20]\">\n                클리커\n            </button>\n        </div>\n\n        <!-- 클리커 서브 선택 -->\n        <div id=\"clicker-selector\" class=\"hidden pointer-events-auto flex flex-wrap justify-center gap-2\">\n            <button onclick=\"selectClicker('clover')\" id=\"btn-clover\" class=\"a2z-btn active px-5 py-1.5 text-xs md:text-sm\">\n                클로버\n            </button>\n            <button onclick=\"selectClicker('omurice')\" id=\"btn-omurice\" class=\"a2z-btn px-5 py-1.5 text-xs md:text-sm\">\n                오므라이스\n            </button>\n            <button onclick=\"selectClicker('dumpling')\" id=\"btn-dumpling\" class=\"a2z-btn px-5 py-1.5 text-xs md:text-sm\">\n                만두\n            </button>\n        </div>\n    </div>\n\n    <!-- 음향 설정 버튼 -->\n    <div class=\"absolute bottom-6 right-6 z-20 flex gap-3\">\n        <button id=\"btn-sound\" onclick=\"toggleSound()\" title=\"음향 설정\" class=\"w-12 h-12 rounded-full border-2 border-[#1C1C20] bg-[#FEFEFE] text-[#1C1C20] flex items-center justify-center hover:bg-[#1C1C20] hover:text-white transition-all\">\n            <i id=\"sound-icon\" class=\"fa-solid fa-volume-high text-lg\"></i>\n        </button>\n    </div>\n\n    <script>\n        /* =========================================================================\n           1. 사운드 웹 오디오 엔진 (키보드 타건음 & 클리커 딸깍음)\n           ========================================================================= */\n        class RealAudioEngine {\n            constructor() {\n                this.ctx = null;\n                this.enabled = true;\n                this.lastSoundTime = 0;\n            }\n\n            init() {\n                if (!this.ctx) {\n                    const AudioContext = window.AudioContext || window.webkitAudioContext;\n                    this.ctx = new AudioContext();\n                }\n                if (this.ctx.state === 'suspended') {\n                    this.ctx.resume();\n                }\n            }\n\n            // 기계식 키보드 타건음 (\"도글-탁!\")\n            playKeycapThock() {\n                if (!this.enabled) return;\n                this.init();\n                const now = this.ctx.currentTime;\n\n                if (now - this.lastSoundTime < 0.05) return;\n                this.lastSoundTime = now;\n\n                const noiseBuf = this.createNoiseBuffer(0.02);\n                const noiseSrc = this.ctx.createBufferSource();\n                const filter = this.ctx.createBiquadFilter();\n                const gain = this.ctx.createGain();\n\n                noiseSrc.buffer = noiseBuf;\n                filter.type = 'bandpass';\n                filter.frequency.setValueAtTime(3100, now);\n                filter.Q.setValueAtTime(3.8, now);\n\n                gain.gain.setValueAtTime(0.5, now);\n                gain.gain.exponentialRampToValueAtTime(0.001, now + 0.018);\n\n                noiseSrc.connect(filter);\n                filter.connect(gain);\n                gain.connect(this.ctx.destination);\n\n                noiseSrc.start(now);\n                noiseSrc.stop(now + 0.02);\n\n                const osc = this.ctx.createOscillator();\n                const oscFilter = this.ctx.createBiquadFilter();\n                const oscGain = this.ctx.createGain();\n\n                osc.type = 'triangle';\n                osc.frequency.setValueAtTime(320, now);\n                osc.frequency.exponentialRampToValueAtTime(110, now + 0.042);\n\n                oscFilter.type = 'lowpass';\n                oscFilter.frequency.setValueAtTime(800, now);\n\n                oscGain.gain.setValueAtTime(0.6, now);\n                oscGain.gain.exponentialRampToValueAtTime(0.001, now + 0.045);\n\n                osc.connect(oscFilter);\n                oscFilter.connect(oscGain);\n                oscGain.connect(this.ctx.destination);\n\n                osc.start(now);\n                osc.stop(now + 0.048);\n            }\n\n            // 클리커 \"딸깍!\" 스위치 클릭음\n            playClickerSnap() {\n                if (!this.enabled) return;\n                this.init();\n                const now = this.ctx.currentTime;\n\n                if (now - this.lastSoundTime < 0.05) return;\n                this.lastSoundTime = now;\n\n                const snapBuf = this.createNoiseBuffer(0.015);\n                const snapSrc = this.ctx.createBufferSource();\n                const snapFilter = this.ctx.createBiquadFilter();\n                const snapGain = this.ctx.createGain();\n\n                snapSrc.buffer = snapBuf;\n                snapFilter.type = 'highpass';\n                snapFilter.frequency.setValueAtTime(3500, now);\n\n                snapGain.gain.setValueAtTime(0.65, now);\n                snapGain.gain.exponentialRampToValueAtTime(0.001, now + 0.014);\n\n                snapSrc.connect(snapFilter);\n                snapFilter.connect(snapGain);\n                snapGain.connect(this.ctx.destination);\n\n                snapSrc.start(now);\n                snapSrc.stop(now + 0.015);\n\n                setTimeout(() => {\n                    if (!this.ctx) return;\n                    const t = this.ctx.currentTime;\n                    const popOsc = this.ctx.createOscillator();\n                    const popGain = this.ctx.createGain();\n\n                    popOsc.type = 'sine';\n                    popOsc.frequency.setValueAtTime(1450, t);\n                    popOsc.frequency.exponentialRampToValueAtTime(400, t + 0.02);\n\n                    popGain.gain.setValueAtTime(0.38, t);\n                    popGain.gain.exponentialRampToValueAtTime(0.001, t + 0.022);\n\n                    popOsc.connect(popGain);\n                    popGain.connect(this.ctx.destination);\n\n                    popOsc.start(t);\n                    popOsc.stop(t + 0.025);\n                }, 10);\n            }\n\n            createNoiseBuffer(duration) {\n                const bufferSize = this.ctx.sampleRate * duration;\n                const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);\n                const data = buffer.getChannelData(0);\n                for (let i = 0; i < bufferSize; i++) {\n                    data[i] = Math.random() * 2 - 1;\n                }\n                return buffer;\n            }\n        }\n\n        const soundEngine = new RealAudioEngine();\n\n        /* =========================================================================\n           2. THREE.JS 3D 씬 및 모델링\n           ========================================================================= */\n        let scene, camera, renderer, currentMeshGroup;\n        let activeMainTab = 'keycap';\n        let currentClickerType = 'clover';\n\n        let raycaster = new THREE.Raycaster();\n        let mouse = new THREE.Vector2();\n        let isPointerDown = false;\n        let previousMousePosition = { x: 0, y: 0 };\n\n        let pressableParts = [];\n\n        function init3D() {\n            const canvas = document.getElementById('webgl-canvas');\n\n            scene = new THREE.Scene();\n            scene.background = new THREE.Color(0xfefeef);\n\n            camera = new THREE.PerspectiveCamera(36, window.innerWidth / window.innerHeight, 0.1, 100);\n            camera.position.set(2.4, 3.2, 4.2);\n            camera.lookAt(0, -0.1, 0);\n\n            renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: false });\n            renderer.setSize(window.innerWidth, window.innerHeight);\n            renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n            renderer.shadowMap.enabled = true;\n            renderer.shadowMap.type = THREE.PCFSoftShadowMap;\n\n            const ambientLight = new THREE.AmbientLight(0xffffff, 0.52);\n            scene.add(ambientLight);\n\n            const mainLight = new THREE.DirectionalLight(0xffffff, 0.55);\n            mainLight.position.set(4, 7, 5);\n            mainLight.castShadow = true;\n            mainLight.shadow.mapSize.width = 1024;\n            mainLight.shadow.mapSize.height = 1024;\n            scene.add(mainLight);\n\n            const fillLight1 = new THREE.DirectionalLight(0xfffae6, 0.35);\n            fillLight1.position.set(-4, 3, -3);\n            scene.add(fillLight1);\n\n            const fillLight2 = new THREE.DirectionalLight(0xffffff, 0.3);\n            fillLight2.position.set(0, -3, 3);\n            scene.add(fillLight2);\n\n            currentMeshGroup = new THREE.Group();\n            scene.add(currentMeshGroup);\n\n            buildKeycapTesterModel();\n            setupEventListeners();\n            animate();\n        }\n\n        function clearCurrentGroup() {\n            pressableParts = [];\n            while (currentMeshGroup.children.length > 0) {\n                const obj = currentMeshGroup.children[0];\n                if (obj.geometry) obj.geometry.dispose();\n                if (obj.material) {\n                    if (Array.isArray(obj.material)) obj.material.forEach(m => m.dispose());\n                    else obj.material.dispose();\n                }\n                currentMeshGroup.remove(obj);\n            }\n            currentMeshGroup.rotation.set(0, 0, 0);\n            currentMeshGroup.position.set(0, 0, 0);\n            currentMeshGroup.scale.set(1, 1, 1);\n        }\n\n        /* -------------------------------------------------------------------------\n           [모델 1] 키캡 (투명 아크릴 하우징 depthWrite 보정)\n           ------------------------------------------------------------------------- */\n        function buildKeycapTesterModel() {\n            clearCurrentGroup();\n\n            const acrylicGeo = new THREE.BoxGeometry(4.4, 0.72, 1.3);\n            const acrylicMat = new THREE.MeshPhysicalMaterial({\n                color: 0xf0f4f8,\n                roughness: 0.1,\n                metalness: 0.05,\n                transmission: 0.65,\n                opacity: 0.95,\n                transparent: true,\n                depthWrite: true,\n                clearcoat: 1.0,\n                clearcoatRoughness: 0.1\n            });\n            const acrylicBase = new THREE.Mesh(acrylicGeo, acrylicMat);\n            acrylicBase.position.y = -0.38;\n            acrylicBase.castShadow = true;\n            acrylicBase.receiveShadow = true;\n            currentMeshGroup.add(acrylicBase);\n\n            const keyColors = [0xff9ebb, 0x80e5ff, 0xe0aaff, 0xffee93];\n            const xPositions = [-1.5, -0.5, 0.5, 1.5];\n\n            const switchHousingMat = new THREE.MeshPhysicalMaterial({ color: 0xffffff, transparent: true, opacity: 0.8, roughness: 0.2, depthWrite: true });\n            const stemMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.3 });\n            const contactMat = new THREE.MeshStandardMaterial({ color: 0xd4af37, metalness: 0.8, roughness: 0.2 });\n\n            xPositions.forEach((xPos, idx) => {\n                const socketMesh = new THREE.Mesh(new THREE.BoxGeometry(0.85, 0.45, 0.85), switchHousingMat);\n                socketMesh.position.set(xPos, -0.12, 0);\n                currentMeshGroup.add(socketMesh);\n\n                const contactMesh = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.28, 0.38), contactMat);\n                contactMesh.position.set(xPos - 0.18, -0.12, 0);\n                currentMeshGroup.add(contactMesh);\n\n                const stemGroup = new THREE.Group();\n                const stemV = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.4, 0.35), stemMat);\n                const stemH = new THREE.Mesh(new THREE.BoxGeometry(0.35, 0.4, 0.15), stemMat);\n                stemGroup.add(stemV);\n                stemGroup.add(stemH);\n                stemGroup.position.set(xPos, 0.1, 0);\n                currentMeshGroup.add(stemGroup);\n\n                const keycapGroup = new THREE.Group();\n                const capGeo = new THREE.CylinderGeometry(0.4, 0.52, 0.48, 4, 1);\n                capGeo.rotateY(Math.PI / 4);\n\n                const capMat = new THREE.MeshPhysicalMaterial({\n                    color: keyColors[idx],\n                    roughness: 0.35,\n                    clearcoat: 0.35,\n                    clearcoatRoughness: 0.2\n                });\n\n                const capMesh = new THREE.Mesh(capGeo, capMat);\n                capMesh.castShadow = true;\n                keycapGroup.add(capMesh);\n\n                keycapGroup.position.set(xPos, 0.48, 0);\n                currentMeshGroup.add(keycapGroup);\n\n                pressableParts.push({\n                    mesh: keycapGroup,\n                    origY: 0.48,\n                    pressY: 0.26,\n                    currentY: 0.48,\n                    isPressed: false,\n                    type: 'keycap'\n                });\n            });\n\n            currentMeshGroup.rotation.y = -Math.PI / 8;\n        }\n\n        /* -------------------------------------------------------------------------\n           [모델 2] 클로버 클리커 (슬림하우징 & 팁 밀착 4잎)\n           ------------------------------------------------------------------------- */\n        function buildCloverClicker() {\n            clearCurrentGroup();\n\n            const housingMat = new THREE.MeshStandardMaterial({ color: 0x186a3b, roughness: 0.4 });\n            const cloverHousingGroup = new THREE.Group();\n\n            const lobeGeo = new THREE.CylinderGeometry(0.58, 0.58, 0.28, 32);\n            const dist = 0.38;\n            const angles = [0, Math.PI / 2, Math.PI, Math.PI * 1.5];\n\n            angles.forEach(ang => {\n                const lobe = new THREE.Mesh(lobeGeo, housingMat);\n                lobe.position.set(Math.cos(ang) * dist, -0.14, Math.sin(ang) * dist);\n                lobe.castShadow = true;\n                cloverHousingGroup.add(lobe);\n            });\n\n            const centerCore = new THREE.Mesh(new THREE.CylinderGeometry(0.58, 0.58, 0.28, 32), housingMat);\n            centerCore.position.y = -0.14;\n            cloverHousingGroup.add(centerCore);\n\n            currentMeshGroup.add(cloverHousingGroup);\n\n            const heartShape = new THREE.Shape();\n            heartShape.moveTo(0, 0);\n            heartShape.bezierCurveTo(-0.05, 0.1, -0.32, 0.22, -0.32, 0.48);\n            heartShape.bezierCurveTo(-0.32, 0.72, -0.14, 0.82, 0, 0.62);\n            heartShape.bezierCurveTo(0.14, 0.82, 0.32, 0.72, 0.32, 0.48);\n            heartShape.bezierCurveTo(0.32, 0.22, 0.05, 0.1, 0, 0);\n\n            const extrudeSettings = { depth: 0.32, bevelEnabled: true, bevelThickness: 0.04, bevelSize: 0.03, bevelSegments: 3 };\n            const heartGeo = new THREE.ExtrudeGeometry(heartShape, extrudeSettings);\n            heartGeo.rotateX(-Math.PI / 2);\n\n            angles.forEach((ang) => {\n                const leafGroup = new THREE.Group();\n                const leafMat = new THREE.MeshStandardMaterial({\n                    color: 0x2ecc71,\n                    emissive: 0x000000,\n                    roughness: 0.3\n                });\n\n                const heartMesh = new THREE.Mesh(heartGeo, leafMat);\n                heartMesh.castShadow = true;\n                leafGroup.add(heartMesh);\n\n                leafGroup.rotation.y = -ang - Math.PI / 2;\n                leafGroup.position.set(0, 0.02, 0);\n                currentMeshGroup.add(leafGroup);\n\n                pressableParts.push({\n                    mesh: leafGroup,\n                    leafMat: leafMat,\n                    origY: 0.02,\n                    pressY: -0.1,\n                    currentY: 0.02,\n                    isPressed: false,\n                    type: 'clicker'\n                });\n            });\n        }\n\n        /* -------------------------------------------------------------------------\n           [모델 3] 오므라이스 클리커 (짜낸 3D 케첩 라인 아트 & 도톰한 가니쉬 전면 노출)\n           ------------------------------------------------------------------------- */\n        function buildOmuriceClicker() {\n            clearCurrentGroup();\n\n            // 1) 접시\n            const plateGeo = new THREE.CylinderGeometry(1.7, 1.55, 0.18, 32);\n            plateGeo.scale(1.2, 1.0, 1.0);\n            const plateMat = new THREE.MeshStandardMaterial({ color: 0xf8f9fa, roughness: 0.25 });\n            const plateMesh = new THREE.Mesh(plateGeo, plateMat);\n            plateMesh.position.y = -0.28;\n            plateMesh.castShadow = true;\n            currentMeshGroup.add(plateMesh);\n\n            const sauceRingGeo = new THREE.TorusGeometry(1.48, 0.035, 8, 32);\n            sauceRingGeo.rotateX(Math.PI / 2);\n            sauceRingGeo.scale(1.18, 0.96, 1.0);\n            const sauceMat = new THREE.MeshStandardMaterial({ color: 0xe53935, roughness: 0.3 });\n            const sauceRing = new THREE.Mesh(sauceRingGeo, sauceMat);\n            sauceRing.position.y = -0.18;\n            currentMeshGroup.add(sauceRing);\n\n            const demiGeo = new THREE.CylinderGeometry(1.38, 1.38, 0.06, 32);\n            demiGeo.scale(1.15, 1.0, 0.9);\n            const demiMat = new THREE.MeshStandardMaterial({ color: 0x4a2311, roughness: 0.4 });\n            const demiMesh = new THREE.Mesh(demiGeo, demiMat);\n            demiMesh.position.y = -0.17;\n            currentMeshGroup.add(demiMesh);\n\n            // 2) 가니쉬 (계란 밖 접시 우측/좌측으로 끌어올려 100% 또렷이 노출)\n            const peaGeo = new THREE.SphereGeometry(0.12, 12, 12);\n            const peaMat = new THREE.MeshStandardMaterial({ color: 0x27ae60, roughness: 0.3 });\n            [ [0.85, 0.0, 0.42], [0.98, 0.0, 0.3], [0.92, 0.0, 0.54], [1.08, 0.0, 0.45] ].forEach(p => {\n                const pea = new THREE.Mesh(peaGeo, peaMat);\n                pea.position.set(p[0], p[1], p[2]);\n                currentMeshGroup.add(pea);\n            });\n\n            const tomatoGeo = new THREE.SphereGeometry(0.18, 16, 16);\n            const tomatoMat = new THREE.MeshStandardMaterial({ color: 0xe53935, roughness: 0.2 });\n            [ [-0.85, 0.04, 0.52], [-1.02, 0.04, 0.38] ].forEach(p => {\n                const tom = new THREE.Mesh(tomatoGeo, tomatoMat);\n                tom.position.set(p[0], p[1], p[2]);\n                currentMeshGroup.add(tom);\n            });\n\n            // 3) 노란 계란 바디\n            const eggGroup = new THREE.Group();\n            const eggGeo = new THREE.SphereGeometry(1.0, 32, 32);\n            eggGeo.scale(1.1, 0.5, 0.82);\n            const eggMat = new THREE.MeshStandardMaterial({ color: 0xffca28, roughness: 0.45 });\n\n            const eggMesh = new THREE.Mesh(eggGeo, eggMat);\n            eggMesh.castShadow = true;\n            eggGroup.add(eggMesh);\n\n            // 4) 진짜 튜브로 짜낸 듯한 3D 케첩 라인 아트 (TubeGeometry)\n            const curvePoints = [];\n            const numPts = 60;\n            const a = 1.1, b = 0.5, c = 0.82;\n\n            for (let i = 0; i <= numPts; i++) {\n                const t = (i / numPts) * Math.PI * 2;\n                // 2D 하트 라인 수학 공식\n                const hx = (16 * Math.pow(Math.sin(t), 3)) / 16.0 * 0.36;\n                const hz = -(13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t)) / 16.0 * 0.36;\n                \n                // 계란 타원체 곡면에 착 밀착 계산\n                const radSq = Math.pow(hx / a, 2) + Math.pow(hz / c, 2);\n                const hy = b * Math.sqrt(Math.max(0.001, 1.0 - radSq)) + 0.015;\n                \n                curvePoints.push(new THREE.Vector3(hx, hy, hz));\n            }\n\n            const heartCurve = new THREE.CatmullRomCurve3(curvePoints, true);\n            const ketchupTubeGeo = new THREE.TubeGeometry(heartCurve, 64, 0.032, 12, true);\n\n            const ketchupMat = new THREE.MeshPhysicalMaterial({\n                color: 0xd63031,\n                roughness: 0.15,\n                clearcoat: 1.0,\n                clearcoatRoughness: 0.1\n            });\n\n            const ketchupMesh = new THREE.Mesh(ketchupTubeGeo, ketchupMat);\n            ketchupMesh.castShadow = true;\n            eggGroup.add(ketchupMesh);\n\n            eggGroup.position.y = 0.12;\n            currentMeshGroup.add(eggGroup);\n\n            pressableParts.push({\n                mesh: eggGroup,\n                origY: 0.12,\n                pressY: -0.06,\n                currentY: 0.12,\n                isPressed: false,\n                type: 'clicker'\n            });\n        }\n\n        /* -------------------------------------------------------------------------\n           [모델 4] 만두 클리커 (고소한 만두피 색상 & 감싸는 찜기)\n           ------------------------------------------------------------------------- */\n        function buildDumplingClicker() {\n            clearCurrentGroup();\n\n            const steamerGeo = new THREE.CylinderGeometry(1.25, 1.25, 0.75, 32, 1, true);\n            const steamerMat = new THREE.MeshStandardMaterial({\n                color: 0xc89d5c,\n                roughness: 0.6,\n                side: THREE.DoubleSide\n            });\n            const steamer = new THREE.Mesh(steamerGeo, steamerMat);\n            steamer.position.y = -0.1;\n            steamer.castShadow = true;\n            currentMeshGroup.add(steamer);\n\n            const ringGeo = new THREE.TorusGeometry(1.26, 0.045, 8, 32);\n            ringGeo.rotateX(Math.PI / 2);\n            const ringMat = new THREE.MeshStandardMaterial({ color: 0x936b33, roughness: 0.5 });\n\n            const r1 = new THREE.Mesh(ringGeo, ringMat);\n            r1.position.y = 0.27;\n            currentMeshGroup.add(r1);\n\n            const r2 = new THREE.Mesh(ringGeo, ringMat);\n            r2.position.y = -0.47;\n            currentMeshGroup.add(r2);\n\n            const innerFloor = new THREE.Mesh(new THREE.CylinderGeometry(1.2, 1.2, 0.1, 32), new THREE.MeshStandardMaterial({ color: 0x5a3b1a, roughness: 0.8 }));\n            innerFloor.position.y = -0.15;\n            currentMeshGroup.add(innerFloor);\n\n            const dumplingGroup = new THREE.Group();\n            const dumplingGeo = new THREE.SphereGeometry(1.18, 48, 32);\n            dumplingGeo.scale(1.0, 0.76, 1.0);\n\n            const posAttr = dumplingGeo.attributes.position;\n            for (let i = 0; i < posAttr.count; i++) {\n                let x = posAttr.getX(i);\n                let y = posAttr.getY(i);\n                let z = posAttr.getZ(i);\n\n                if (y > -0.1) {\n                    const angle = Math.atan2(z, x);\n                    const heightFactor = Math.pow((y + 0.1) / 0.8, 1.2);\n                    const fold = Math.sin(angle * 16) * 0.08 * heightFactor;\n\n                    posAttr.setXYZ(i, x + Math.cos(angle) * fold, y, z + Math.sin(angle) * fold);\n                }\n            }\n            dumplingGeo.computeVertexNormals();\n\n            const dumplingMat = new THREE.MeshStandardMaterial({\n                color: 0xf5efe0,\n                roughness: 0.55,\n                metalness: 0.05\n            });\n\n            const dumplingMesh = new THREE.Mesh(dumplingGeo, dumplingMat);\n            dumplingMesh.castShadow = true;\n            dumplingGroup.add(dumplingMesh);\n\n            dumplingGroup.position.y = 0.22;\n            currentMeshGroup.add(dumplingGroup);\n\n            pressableParts.push({\n                mesh: dumplingGroup,\n                origY: 0.22,\n                pressY: 0.02,\n                currentY: 0.22,\n                isPressed: false,\n                type: 'clicker'\n            });\n        }\n\n        /* =========================================================================\n           3. 마우스/터치 물리 반응 및 애니메이션\n           ========================================================================= */\n        function setupEventListeners() {\n            const canvas = document.getElementById('webgl-canvas');\n            document.addEventListener('contextmenu', e => e.preventDefault());\n\n            canvas.addEventListener('pointerdown', onPointerDown);\n            canvas.addEventListener('pointermove', onPointerMove);\n            canvas.addEventListener('pointerup', onPointerUp);\n            canvas.addEventListener('pointercancel', onPointerUp);\n\n            window.addEventListener('resize', onWindowResize);\n        }\n\n        function updateMouseCoords(e) {\n            mouse.x = (e.clientX / window.innerWidth) * 2 - 1;\n            mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;\n        }\n\n        function onPointerDown(e) {\n            isPointerDown = true;\n            updateMouseCoords(e);\n            previousMousePosition = { x: e.clientX, y: e.clientY };\n\n            raycaster.setFromCamera(mouse, camera);\n\n            for (let i = 0; i < pressableParts.length; i++) {\n                const part = pressableParts[i];\n                const intersects = raycaster.intersectObject(part.mesh, true);\n                if (intersects.length > 0) {\n                    part.isPressed = true;\n\n                    if (part.type === 'keycap') {\n                        soundEngine.playKeycapThock();\n                    } else {\n                        soundEngine.playClickerSnap();\n                        if (part.leafMat) {\n                            part.leafMat.emissive.setHex(0x33ff33);\n                        }\n                    }\n                    break;\n                }\n            }\n        }\n\n        function onPointerMove(e) {\n            if (!isPointerDown) return;\n\n            const deltaX = e.clientX - previousMousePosition.x;\n            const deltaY = e.clientY - previousMousePosition.y;\n\n            currentMeshGroup.rotation.y += deltaX * 0.008;\n            currentMeshGroup.rotation.x += deltaY * 0.008;\n\n            previousMousePosition = { x: e.clientX, y: e.clientY };\n        }\n\n        function onPointerUp() {\n            isPointerDown = false;\n            pressableParts.forEach(part => {\n                part.isPressed = false;\n                if (part.leafMat) {\n                    part.leafMat.emissive.setHex(0x000000);\n                }\n            });\n        }\n\n        function updatePhysics() {\n            pressableParts.forEach(part => {\n                const targetY = part.isPressed ? part.pressY : part.origY;\n                part.currentY += (targetY - part.currentY) * 0.38;\n                part.mesh.position.y = part.currentY;\n            });\n        }\n\n        function animate() {\n            requestAnimationFrame(animate);\n            updatePhysics();\n            renderer.render(scene, camera);\n        }\n\n        function onWindowResize() {\n            camera.aspect = window.innerWidth / window.innerHeight;\n            camera.updateProjectionMatrix();\n            renderer.setSize(window.innerWidth, window.innerHeight);\n        }\n\n        /* =========================================================================\n           4. 탭 제어\n           ========================================================================= */\n        function switchMainTab(mainTab) {\n            activeMainTab = mainTab;\n\n            const btnKeycap = document.getElementById('tab-keycap');\n            const btnClicker = document.getElementById('tab-clicker');\n            const clickerSelector = document.getElementById('clicker-selector');\n\n            if (mainTab === 'keycap') {\n                btnKeycap.classList.add('active');\n                btnClicker.classList.remove('active');\n                clickerSelector.classList.add('hidden');\n\n                buildKeycapTesterModel();\n            } else {\n                btnClicker.classList.add('active');\n                btnKeycap.classList.remove('active');\n                clickerSelector.classList.remove('hidden');\n\n                selectClicker(currentClickerType);\n            }\n        }\n\n        function selectClicker(type) {\n            currentClickerType = type;\n\n            ['clover', 'omurice', 'dumpling'].forEach(t => {\n                const btn = document.getElementById(`btn-${t}`);\n                if (t === type) btn.classList.add('active');\n                else btn.classList.remove('active');\n            });\n\n            if (type === 'clover') buildCloverClicker();\n            else if (type === 'omurice') buildOmuriceClicker();\n            else if (type === 'dumpling') buildDumplingClicker();\n        }\n\n        function toggleSound() {\n            soundEngine.enabled = !soundEngine.enabled;\n            const soundIcon = document.getElementById('sound-icon');\n            if (soundEngine.enabled) {\n                soundIcon.className = 'fa-solid fa-volume-high text-lg';\n            } else {\n                soundIcon.className = 'fa-solid fa-volume-xmark text-lg text-red-500';\n            }\n        }\n\n        window.onload = function() {\n            init3D();\n            switchMainTab('keycap');\n        };\n    <\/script>\n</body>\n</html>", "Tangle.html": "<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n    <title>3D 탱글 (Tangle) 피젯</title>\n    <!-- SUIT Variable Font -->\n    <link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/gh/sun-typeface/SUIT@2/fonts/variable/woff2/SUIT-Variable.css\">\n    <!-- Tailwind CSS -->\n    <script src=\"https://cdn.tailwindcss.com\"><\/script>\n    <!-- Three.js r128 -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"><\/script>\n    <!-- FontAwesome Icons -->\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n\n    <style>\n        :root {\n            --ink: #1C1C20;\n            --paper: #FEFEFE;\n            --g1: #E1E5EA;\n            --r-pill: 38px;\n        }\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n            user-select: none;\n            -webkit-user-select: none;\n            touch-action: none;\n            font-family: 'SUIT Variable', -apple-system, BlinkMacSystemFont, system-ui, sans-serif;\n        }\n\n        body, html {\n            width: 100vw;\n            height: 100vh;\n            overflow: hidden;\n            background-color: #fcfbf7;\n        }\n\n        .a2z-btn {\n            background-color: var(--paper);\n            color: var(--ink);\n            border: 2px solid var(--ink);\n            border-radius: var(--r-pill);\n            font-weight: 800;\n            transition: all 0.15s ease;\n        }\n\n        .a2z-btn:hover {\n            background-color: var(--g1);\n        }\n\n        .a2z-btn.active {\n            background-color: var(--ink);\n            color: var(--paper);\n        }\n\n        #webgl-canvas {\n            width: 100vw;\n            height: 100vh;\n            display: block;\n            cursor: grab;\n        }\n\n        #webgl-canvas:active {\n            cursor: grabbing;\n        }\n    </style>\n</head>\n<body class=\"relative\">\n\n    <!-- 3D Full Screen WebGL Canvas -->\n    <canvas id=\"webgl-canvas\"></canvas>\n\n    <!-- 상단 재질 선택 탭 UI -->\n    <div class=\"absolute top-6 left-0 right-0 z-20 flex justify-center pointer-events-none px-4\">\n        <div class=\"pointer-events-auto flex bg-[#FEFEFE] border-2 border-[#1C1C20] rounded-full p-1 shadow-sm gap-1\">\n            <button id=\"mat-opaque\" onclick=\"setMaterialType('opaque')\" class=\"a2z-btn active px-6 py-2 text-xs md:text-sm\">\n                불투명\n            </button>\n            <button id=\"mat-transparent\" onclick=\"setMaterialType('transparent')\" class=\"a2z-btn px-6 py-2 text-xs md:text-sm\">\n                투명\n            </button>\n            <button id=\"mat-metallic\" onclick=\"setMaterialType('metallic')\" class=\"a2z-btn px-6 py-2 text-xs md:text-sm\">\n                메탈릭\n            </button>\n        </div>\n    </div>\n\n    <!-- 우측 하단 소리 토글 버튼 -->\n    <div class=\"absolute bottom-6 right-6 z-20 flex gap-3\">\n        <button id=\"btn-sound\" onclick=\"toggleSound()\" title=\"음향 설정\" class=\"w-12 h-12 rounded-full border-2 border-[#1C1C20] bg-[#FEFEFE] text-[#1C1C20] flex items-center justify-center hover:bg-[#1C1C20] hover:text-white transition-all shadow-sm\">\n            <i id=\"sound-icon\" class=\"fa-solid fa-volume-high text-lg\"></i>\n        </button>\n    </div>\n\n    <script>\n        /* =========================================================================\n           1. 탱글 오디오 엔진 (실감 나는 플라스틱 관절 달그닥 소리)\n           ========================================================================= */\n        class TangleAudioEngine {\n            constructor() {\n                this.ctx = null;\n                this.enabled = true;\n                this.lastSoundTime = 0;\n            }\n\n            init() {\n                if (!this.ctx) {\n                    const AudioContext = window.AudioContext || window.webkitAudioContext;\n                    this.ctx = new AudioContext();\n                }\n                if (this.ctx.state === 'suspended') {\n                    this.ctx.resume();\n                }\n            }\n\n            playClack(intensity = 1.0) {\n                if (!this.enabled) return;\n                this.init();\n                const now = this.ctx.currentTime;\n\n                if (now - this.lastSoundTime < 0.04) return;\n                this.lastSoundTime = now;\n\n                const t = now;\n                const vol = Math.min(0.8, 0.4 * intensity);\n\n                const bufSize = this.ctx.sampleRate * 0.012;\n                const buf = this.ctx.createBuffer(1, bufSize, this.ctx.sampleRate);\n                const data = buf.getChannelData(0);\n                for (let i = 0; i < bufSize; i++) {\n                    data[i] = Math.random() * 2 - 1;\n                }\n\n                const src = this.ctx.createBufferSource();\n                const filter = this.ctx.createBiquadFilter();\n                const gain = this.ctx.createGain();\n\n                src.buffer = buf;\n                filter.type = 'bandpass';\n                filter.frequency.setValueAtTime(2800 + Math.random() * 400, t);\n                filter.Q.setValueAtTime(6.0, t);\n\n                gain.gain.setValueAtTime(vol, t);\n                gain.gain.exponentialRampToValueAtTime(0.001, t + 0.011);\n\n                src.connect(filter);\n                filter.connect(gain);\n                gain.connect(this.ctx.destination);\n\n                src.start(t);\n                src.stop(t + 0.012);\n\n                const osc = this.ctx.createOscillator();\n                const oscGain = this.ctx.createGain();\n\n                osc.type = 'triangle';\n                osc.frequency.setValueAtTime(750, t);\n                osc.frequency.exponentialRampToValueAtTime(180, t + 0.016);\n\n                oscGain.gain.setValueAtTime(vol * 0.5, t);\n                oscGain.gain.exponentialRampToValueAtTime(0.001, t + 0.016);\n\n                osc.connect(oscGain);\n                oscGain.connect(this.ctx.destination);\n\n                osc.start(t);\n                osc.stop(t + 0.018);\n            }\n        }\n\n        const soundEngine = new TangleAudioEngine();\n\n        /* =========================================================================\n           2. 3D 물리 시뮬레이션 및 메쉬 생성 (Three.js)\n           ========================================================================= */\n        let scene, camera, renderer;\n        const NUM_NODES = 20; // 20개의 마디로 구성된 무한 고리\n        const LINK_REST_LENGTH = 0.38; // 마디 간 기본 거리\n        const TUBE_RADIUS = 0.092;\n\n        let nodes = [];\n        let velHistory = [];\n        let segmentMeshes = [];\n\n        let currentMaterialType = 'opaque'; // 'opaque', 'transparent', 'metallic'\n\n        // 인터랙션 상태\n        let raycaster = new THREE.Raycaster();\n        let mouse = new THREE.Vector2();\n        let draggedNodeIndex = -1;\n        let isDragging = false;\n        let dragPlane = new THREE.Plane();\n        let planeIntersect = new THREE.Vector3();\n\n        // 불투명 2색 정밀 컬러 (선명하고 또렷한 파스텔 핑크 & 스카이블루)\n        const OPAQUE_PINK = 0xf06292;\n        const OPAQUE_SKYBLUE = 0x4fc3f7;\n\n        // 투명 & 메탈릭 컬러 (또렷한 비비드 투명 핑크 & 핫핑크 메탈릭)\n        const SINGLE_PINK_TRANSPARENT = 0xff2a6d;\n        const SINGLE_HOT_PINK_METALLIC = 0xff007f;\n\n        function init3D() {\n            const canvas = document.getElementById('webgl-canvas');\n\n            scene = new THREE.Scene();\n            scene.background = new THREE.Color(0xfcfbf7);\n\n            camera = new THREE.PerspectiveCamera(38, window.innerWidth / window.innerHeight, 0.1, 100);\n            camera.position.set(0, 0, 5.5);\n            camera.lookAt(0, 0, 0);\n\n            renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: false });\n            renderer.setSize(window.innerWidth, window.innerHeight);\n            renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n            renderer.shadowMap.enabled = true;\n            renderer.shadowMap.type = THREE.PCFSoftShadowMap;\n\n            // 스튜디오 풍부한 조명\n            const ambientLight = new THREE.AmbientLight(0xffffff, 0.85);\n            scene.add(ambientLight);\n\n            const dirLight1 = new THREE.DirectionalLight(0xffffff, 0.9);\n            dirLight1.position.set(5, 8, 6);\n            dirLight1.castShadow = true;\n            dirLight1.shadow.mapSize.width = 1024;\n            dirLight1.shadow.mapSize.height = 1024;\n            scene.add(dirLight1);\n\n            const dirLight2 = new THREE.DirectionalLight(0xfff0f5, 0.65);\n            dirLight2.position.set(-5, -2, -3);\n            scene.add(dirLight2);\n\n            // 보석 및 메탈릭 반사를 위한 포인트 조명\n            const pointLight1 = new THREE.PointLight(0xffffff, 1.0, 10);\n            pointLight1.position.set(2, 3, 4);\n            scene.add(pointLight1);\n\n            const pointLight2 = new THREE.PointLight(0xffffff, 0.7, 10);\n            pointLight2.position.set(-3, -1, 3);\n            scene.add(pointLight2);\n\n            buildClosedLoopTangle();\n            setupEventListeners();\n            animate();\n        }\n\n        /* -------------------------------------------------------------------------\n           재질 생성 함수\n           ------------------------------------------------------------------------- */\n        function createMaterialForIndex(index, type) {\n            if (type === 'transparent') {\n                return new THREE.MeshPhysicalMaterial({\n                    color: SINGLE_PINK_TRANSPARENT,\n                    roughness: 0.08,\n                    metalness: 0.0,\n                    transmission: 0.72,\n                    opacity: 0.95,\n                    transparent: true,\n                    clearcoat: 1.0,\n                    clearcoatRoughness: 0.03,\n                    ior: 1.48,\n                    reflectivity: 0.92\n                });\n            } else if (type === 'metallic') {\n                return new THREE.MeshStandardMaterial({\n                    color: SINGLE_HOT_PINK_METALLIC,\n                    roughness: 0.15,\n                    metalness: 0.88\n                });\n            } else {\n                const color = (index % 2 === 0) ? OPAQUE_PINK : OPAQUE_SKYBLUE;\n                return new THREE.MeshPhysicalMaterial({\n                    color: color,\n                    roughness: 0.25,\n                    metalness: 0.0,\n                    clearcoat: 0.4,\n                    clearcoatRoughness: 0.1,\n                    transparent: false,\n                    opacity: 1.0\n                });\n            }\n        }\n\n        /* -------------------------------------------------------------------------\n           3D 닫힌 고리 (Closed Loop) 생성\n           ------------------------------------------------------------------------- */\n        function buildClosedLoopTangle() {\n            nodes = [];\n            velHistory = [];\n            segmentMeshes = [];\n\n            for (let i = 0; i < NUM_NODES; i++) {\n                const t = (i / NUM_NODES) * Math.PI * 2;\n                const R = 1.25;\n                const rWave = 0.45;\n\n                const x = (R + rWave * Math.cos(3 * t)) * Math.cos(t);\n                const y = (R + rWave * Math.cos(3 * t)) * Math.sin(t);\n                const z = rWave * Math.sin(3 * t);\n\n                nodes.push(new THREE.Vector3(x, y, z));\n                velHistory.push(new THREE.Vector3(0, 0, 0));\n            }\n\n            for (let i = 0; i < NUM_NODES; i++) {\n                const mat = createMaterialForIndex(i, currentMaterialType);\n                const segMesh = new THREE.Mesh(new THREE.BufferGeometry(), mat);\n                segMesh.castShadow = true;\n                segMesh.receiveShadow = true;\n                segMesh.userData = { index: i };\n                scene.add(segMesh);\n                segmentMeshes.push(segMesh);\n            }\n\n            updateTangleMeshGeometries();\n        }\n\n        /* -------------------------------------------------------------------------\n           재질 타입 변경 탭 이벤트 handler\n           ------------------------------------------------------------------------- */\n        function setMaterialType(type) {\n            currentMaterialType = type;\n\n            ['opaque', 'transparent', 'metallic'].forEach(t => {\n                const btn = document.getElementById(`mat-${t}`);\n                if (t === type) btn.classList.add('active');\n                else btn.classList.remove('active');\n            });\n\n            for (let i = 0; i < NUM_NODES; i++) {\n                if (segmentMeshes[i].material) segmentMeshes[i].material.dispose();\n                segmentMeshes[i].material = createMaterialForIndex(i, currentMaterialType);\n            }\n        }\n\n        /* -------------------------------------------------------------------------\n           음향 켜기/끄기 토글\n           ------------------------------------------------------------------------- */\n        function toggleSound() {\n            soundEngine.enabled = !soundEngine.enabled;\n            const soundIcon = document.getElementById('sound-icon');\n            if (soundEngine.enabled) {\n                soundIcon.className = 'fa-solid fa-volume-high text-lg';\n            } else {\n                soundIcon.className = 'fa-solid fa-volume-xmark text-lg text-red-500';\n            }\n        }\n\n        /* -------------------------------------------------------------------------\n           마디 노드 위치에 맞춰 매끈한 3D 튜브 최신화\n           ------------------------------------------------------------------------- */\n        function updateTangleMeshGeometries() {\n            const closedCurve = new THREE.CatmullRomCurve3(nodes, true, 'catmullrom', 0.5);\n\n            for (let i = 0; i < NUM_NODES; i++) {\n                const tStart = i / NUM_NODES;\n                const tEnd = (i + 1) / NUM_NODES;\n\n                const subPts = [];\n                const samples = 12;\n                for (let s = 0; s <= samples; s++) {\n                    const t = tStart + (s / samples) * (tEnd - tStart);\n                    subPts.push(closedCurve.getPoint(t));\n                }\n                const subCurve = new THREE.CatmullRomCurve3(subPts);\n                \n                if (segmentMeshes[i].geometry) segmentMeshes[i].geometry.dispose();\n                segmentMeshes[i].geometry = new THREE.TubeGeometry(subCurve, 14, TUBE_RADIUS, 18, false);\n            }\n        }\n\n        /* -------------------------------------------------------------------------\n           물리 연산 (Position-Based Dynamics & Natural Friction Damping)\n           ------------------------------------------------------------------------- */\n        function solvePhysics() {\n            const friction = 0.91;\n\n            for (let i = 0; i < NUM_NODES; i++) {\n                if (i === draggedNodeIndex && isDragging) continue;\n\n                nodes[i].add(velHistory[i]);\n                velHistory[i].multiplyScalar(friction);\n            }\n\n            const iterations = 12;\n            for (let iter = 0; iter < iterations; iter++) {\n                for (let i = 0; i < NUM_NODES; i++) {\n                    const j = (i + 1) % NUM_NODES;\n\n                    const p1 = nodes[i];\n                    const p2 = nodes[j];\n\n                    const delta = new THREE.Vector3().subVectors(p2, p1);\n                    const currentLen = delta.length();\n                    if (currentLen === 0) continue;\n\n                    const diff = (currentLen - LINK_REST_LENGTH) / currentLen;\n                    const correction = delta.multiplyScalar(diff * 0.5);\n\n                    if (i !== draggedNodeIndex || !isDragging) {\n                        p1.add(correction);\n                    }\n                    if (j !== draggedNodeIndex || !isDragging) {\n                        p2.sub(correction);\n                    }\n                }\n            }\n\n            updateTangleMeshGeometries();\n        }\n\n        /* =========================================================================\n           3. 마우스 / 터치 인터랙션\n           ========================================================================= */\n        function setupEventListeners() {\n            const canvas = document.getElementById('webgl-canvas');\n\n            canvas.addEventListener('pointerdown', onPointerDown);\n            canvas.addEventListener('pointermove', onPointerMove);\n            canvas.addEventListener('pointerup', onPointerUp);\n            canvas.addEventListener('pointercancel', onPointerUp);\n\n            window.addEventListener('resize', onWindowResize);\n        }\n\n        function updateMouseCoords(e) {\n            mouse.x = (e.clientX / window.innerWidth) * 2 - 1;\n            mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;\n        }\n\n        function onPointerDown(e) {\n            updateMouseCoords(e);\n            raycaster.setFromCamera(mouse, camera);\n\n            const intersects = raycaster.intersectObjects(segmentMeshes, true);\n            if (intersects.length > 0) {\n                isDragging = true;\n                const hitObj = intersects[0].object;\n                draggedNodeIndex = hitObj.userData.index;\n\n                const hitPoint = intersects[0].point;\n                dragPlane.setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), hitPoint);\n\n                soundEngine.playClack(1.2);\n            }\n        }\n\n        function onPointerMove(e) {\n            updateMouseCoords(e);\n\n            if (isDragging && draggedNodeIndex !== -1) {\n                raycaster.setFromCamera(mouse, camera);\n                if (raycaster.ray.intersectPlane(dragPlane, planeIntersect)) {\n                    const targetNode = nodes[draggedNodeIndex];\n                    \n                    const moveDelta = new THREE.Vector3().subVectors(planeIntersect, targetNode);\n                    velHistory[draggedNodeIndex].copy(moveDelta.multiplyScalar(0.45));\n                    \n                    targetNode.copy(planeIntersect);\n\n                    if (moveDelta.length() > 0.08) {\n                        soundEngine.playClack(moveDelta.length() * 4);\n                    }\n                }\n            }\n        }\n\n        function onPointerUp() {\n            if (isDragging) {\n                soundEngine.playClack(0.8);\n            }\n            isDragging = false;\n            draggedNodeIndex = -1;\n        }\n\n        function animate() {\n            requestAnimationFrame(animate);\n\n            solvePhysics();\n\n            if (!isDragging) {\n                const time = Date.now() * 0.0008;\n                scene.rotation.y = Math.sin(time * 0.5) * 0.15;\n                scene.rotation.x = Math.cos(time * 0.3) * 0.1;\n            }\n\n            renderer.render(scene, camera);\n        }\n\n        function onWindowResize() {\n            camera.aspect = window.innerWidth / window.innerHeight;\n            camera.updateProjectionMatrix();\n            renderer.setSize(window.innerWidth, window.innerHeight);\n        }\n\n        window.onload = function() {\n            init3D();\n        };\n    <\/script>\n</body>\n</html>", "Dongmyo.html": "<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n    <title>3D 동묘 벼룩시장 거리 탐방</title>\n    <!-- SUIT Variable Font -->\n    <link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/gh/sun-typeface/SUIT@2/fonts/variable/woff2/SUIT-Variable.css\">\n    <!-- Tailwind CSS -->\n    <script src=\"https://cdn.tailwindcss.com\"><\/script>\n    <!-- Three.js r128 -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"><\/script>\n    <!-- FontAwesome Icons -->\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n\n    <style>\n        :root {\n            --ink: #1C1C20;\n            --paper: #FEFEFE;\n            --g1: #E1E5EA;\n            --r-pill: 38px;\n        }\n\n        * {\n            font-family: 'SUIT Variable', -apple-system, BlinkMacSystemFont, system-ui, sans-serif;\n            user-select: none;\n            -webkit-user-select: none;\n            touch-action: none;\n            box-sizing: border-box;\n        }\n\n        body, html {\n            width: 100vw;\n            height: 100vh;\n            margin: 0;\n            padding: 0;\n            overflow: hidden;\n            background-color: #fcfbf7;\n        }\n\n        .a2z-btn {\n            background-color: var(--paper);\n            color: var(--ink);\n            border: 2px solid var(--ink);\n            border-radius: var(--r-pill);\n            font-weight: 800;\n            transition: all 0.15s ease;\n        }\n\n        .a2z-btn:hover {\n            background-color: var(--g1);\n        }\n\n        .a2z-btn.active {\n            background-color: var(--ink);\n            color: var(--paper);\n        }\n\n        #webgl-canvas {\n            width: 100vw;\n            height: 100vh;\n            display: block;\n            cursor: grab;\n        }\n\n        #webgl-canvas:active {\n            cursor: grabbing;\n        }\n\n        /* 열전사 영수증 카드 */\n        .mini-receipt {\n            background: #fffef8;\n            border: 2px solid var(--ink);\n            position: relative;\n            background-image: repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0,0,0,0.02) 2px, rgba(0,0,0,0.02) 4px);\n        }\n    </style>\n</head>\n<body class=\"relative\">\n\n    <!-- 3D WebGL Canvas -->\n    <canvas id=\"webgl-canvas\"></canvas>\n\n    <!-- 상단 UI (HUD & 가게 뒤로가기 버튼) -->\n    <div class=\"absolute top-5 left-0 right-0 z-20 flex flex-col items-center gap-2.5 px-4 pointer-events-none\">\n        \n        <!-- 가게 내부 뷰 전용 뒤로가기 버튼 -->\n        <div id=\"store-back-bar\" class=\"pointer-events-auto hidden\">\n            <button onclick=\"exitStore()\" class=\"a2z-btn px-5 py-2 text-xs md:text-sm bg-yellow-300 hover:bg-yellow-400 flex items-center gap-2 shadow-sm\">\n                <i class=\"fa-solid fa-arrow-left\"></i>\n                <span id=\"store-title-text\">◀ 동묘 거리로 나가기</span>\n            </button>\n        </div>\n\n        <!-- 소지금 및 득템 현황 HUD -->\n        <div class=\"pointer-events-auto flex items-center gap-3 bg-[#FEFEFE] border-2 border-[#1C1C20] rounded-full px-5 py-1.5 shadow-sm text-xs md:text-sm font-black\">\n            <div>지갑: <span id=\"hud-budget\" class=\"text-red-600\">50,000원</span></div>\n            <div class=\"w-0.5 h-3 bg-zinc-300\"></div>\n            <div>득템 보물: <span id=\"hud-count\" class=\"text-blue-600\">0개</span></div>\n        </div>\n    </div>\n\n    <!-- 좌우 드래그 스크롤 가이드 팁 -->\n    <div id=\"scroll-guide-tip\" class=\"absolute top-20 left-0 right-0 z-10 text-center pointer-events-none transition-opacity duration-300\">\n        <span class=\"bg-[#1C1C20]/80 text-white text-[11px] font-bold px-3.5 py-1.5 rounded-full backdrop-blur-xs\">\n            👈 거리를 좌우로 드래그해서 구경하세요! 가게를 클릭하면 입장합니다 👉\n        </span>\n    </div>\n\n    <!-- 하단 영수증 출력 버튼 -->\n    <div class=\"absolute bottom-5 left-0 right-0 z-20 flex justify-center pointer-events-none px-4\">\n        <button onclick=\"toggleReceipt()\" class=\"pointer-events-auto a2z-btn px-7 py-3 text-xs md:text-sm bg-yellow-300 hover:bg-yellow-400 shadow-md flex items-center gap-2\">\n            <i class=\"fa-solid fa-receipt text-base\"></i>\n            <span>동묘 득템 영수증 출력하기</span>\n        </button>\n    </div>\n\n    <!-- 열전사 영수증 모달 -->\n    <div id=\"receipt-modal\" class=\"fixed inset-0 z-40 bg-black/50 backdrop-blur-sm hidden flex items-center justify-center p-4\">\n        <div class=\"mini-receipt rounded-3xl p-6 max-w-sm w-full font-mono text-xs text-[#1C1C20] space-y-3.5 shadow-2xl border-2 border-[#1C1C20]\">\n            <div class=\"text-center pb-3 border-b-2 border-dashed border-[#1C1C20]\">\n                <div class=\"font-black text-lg\">DONGMYO VINTAGE MARKET</div>\n                <div class=\"text-[11px] text-zinc-500 mt-0.5\">동묘 벼룩시장 득템 영수증</div>\n            </div>\n\n            <!-- 구매 내역 -->\n            <div id=\"receipt-items-list\" class=\"space-y-1.5 py-1 text-xs\">\n                <!-- JS dynamic list -->\n            </div>\n\n            <!-- 정산 집계 -->\n            <div class=\"pt-2 border-t-2 border-dashed border-[#1C1C20] space-y-1 font-bold\">\n                <div class=\"flex justify-between\">\n                    <span>총 지출 금액:</span>\n                    <span id=\"receipt-total\" class=\"font-black text-red-600\">0원</span>\n                </div>\n                <div class=\"flex justify-between text-zinc-500 text-[11px]\">\n                    <span>흥정 절약 혜택:</span>\n                    <span id=\"receipt-saved\" class=\"text-green-600\">0원</span>\n                </div>\n                <div class=\"flex justify-between text-zinc-500 text-[11px]\">\n                    <span>남은 지갑 잔액:</span>\n                    <span id=\"receipt-balance\">50,000원</span>\n                </div>\n            </div>\n\n            <!-- 득템 평가 칭호 -->\n            <div class=\"text-center pt-2 border-t-2 border-dashed border-[#1C1C20]\">\n                <span id=\"receipt-badge\" class=\"inline-block bg-[#1C1C20] text-white px-3 py-1 rounded-full text-xs font-bold\">\n                    \"동묘 거리의 힙스터\"\n                </span>\n            </div>\n\n            <div class=\"flex gap-2 pt-1\">\n                <button onclick=\"resetShopping()\" class=\"a2z-btn w-full py-2.5 text-xs bg-[#FEFEFE] hover:bg-[#E1E5EA]\">\n                    🔄 다시 둘러보기\n                </button>\n                <button onclick=\"toggleReceipt()\" class=\"a2z-btn w-full py-2.5 text-xs bg-[#1C1C20] text-white hover:bg-zinc-800\">\n                    닫기\n                </button>\n            </div>\n        </div>\n    </div>\n\n    <script>\n        /* =========================================================================\n           1. 효과음 엔진 (Web Audio API)\n           ========================================================================= */\n        class DongmyoAudioEngine {\n            constructor() { this.ctx = null; }\n\n            init() {\n                if (!this.ctx) {\n                    const AudioContext = window.AudioContext || window.webkitAudioContext;\n                    this.ctx = new AudioContext();\n                }\n                if (this.ctx.state === 'suspended') this.ctx.resume();\n            }\n\n            playBuy() {\n                this.init();\n                const now = this.ctx.currentTime;\n                const osc = this.ctx.createOscillator();\n                const gain = this.ctx.createGain();\n\n                osc.type = 'sine';\n                osc.frequency.setValueAtTime(1200, now);\n                osc.frequency.exponentialRampToValueAtTime(2400, now + 0.09);\n\n                gain.gain.setValueAtTime(0.3, now);\n                gain.gain.exponentialRampToValueAtTime(0.001, now + 0.11);\n\n                osc.connect(gain);\n                gain.connect(this.ctx.destination);\n                osc.start(now);\n                osc.stop(now + 0.11);\n            }\n\n            playEnter() {\n                this.init();\n                const now = this.ctx.currentTime;\n                const osc = this.ctx.createOscillator();\n                const gain = this.ctx.createGain();\n\n                osc.type = 'triangle';\n                osc.frequency.setValueAtTime(440, now);\n                osc.frequency.exponentialRampToValueAtTime(880, now + 0.12);\n\n                gain.gain.setValueAtTime(0.2, now);\n                gain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);\n\n                osc.connect(gain);\n                gain.connect(this.ctx.destination);\n                osc.start(now);\n                osc.stop(now + 0.12);\n            }\n\n            playReceipt() {\n                this.init();\n                const now = this.ctx.currentTime;\n                for (let i = 0; i < 5; i++) {\n                    const bufSize = this.ctx.sampleRate * 0.015;\n                    const buf = this.ctx.createBuffer(1, bufSize, this.ctx.sampleRate);\n                    const data = buf.getChannelData(0);\n                    for (let j = 0; j < bufSize; j++) data[j] = Math.random() * 2 - 1;\n\n                    const src = this.ctx.createBufferSource();\n                    const filter = this.ctx.createBiquadFilter();\n                    const gain = this.ctx.createGain();\n\n                    src.buffer = buf;\n                    filter.type = 'bandpass';\n                    filter.frequency.setValueAtTime(3000 + i * 200, now + i * 0.04);\n\n                    gain.gain.setValueAtTime(0.18, now + i * 0.04);\n                    gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.04 + 0.02);\n\n                    src.connect(filter);\n                    filter.connect(gain);\n                    gain.connect(this.ctx.destination);\n\n                    src.start(now + i * 0.04);\n                    src.stop(now + i * 0.04 + 0.02);\n                }\n            }\n        }\n\n        const soundEngine = new DongmyoAudioEngine();\n\n        /* =========================================================================\n           2. THREE.JS 3D 동묘 거리 & 파스텔 매장 모델링\n           ========================================================================= */\n        let scene, camera, renderer;\n        \n        let currentState = 'STREET';\n        let currentStoreIndex = -1;\n\n        const INITIAL_BUDGET = 50000;\n        let budget = INITIAL_BUDGET;\n        let boughtItems = [];\n\n        const storeXPositions = [-6.8, 0.0, 6.8];\n        let streetCamX = 0.0;\n        let targetCamPos = new THREE.Vector3(0, 2.8, 9.8);\n        let targetLookAt = new THREE.Vector3(0, 1.4, 0);\n        let currentLookAt = new THREE.Vector3(0, 1.4, 0);\n\n        let isDragging = false;\n        let dragStartX = 0;\n        let dragStartCamX = 0;\n        let totalDragDistance = 0;\n\n        let raycaster = new THREE.Raycaster();\n        let mouse = new THREE.Vector2();\n\n        let storeClickMeshes = [];\n        let interactiveItems = [];\n\n        function init3D() {\n            const canvas = document.getElementById('webgl-canvas');\n\n            scene = new THREE.Scene();\n            scene.background = new THREE.Color(0xfcfbf7);\n\n            camera = new THREE.PerspectiveCamera(38, window.innerWidth / window.innerHeight, 0.1, 100);\n            camera.position.copy(targetCamPos);\n            camera.lookAt(targetLookAt);\n\n            renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: false });\n            renderer.setSize(window.innerWidth, window.innerHeight);\n            renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n            renderer.shadowMap.enabled = true;\n            renderer.shadowMap.type = THREE.PCFSoftShadowMap;\n\n            // 라이팅\n            const ambientLight = new THREE.AmbientLight(0xfff9f0, 0.85);\n            scene.add(ambientLight);\n\n            const sunLight = new THREE.DirectionalLight(0xfffae6, 0.95);\n            sunLight.position.set(6, 12, 8);\n            sunLight.castShadow = true;\n            sunLight.shadow.mapSize.width = 1024;\n            sunLight.shadow.mapSize.height = 1024;\n            scene.add(sunLight);\n\n            const fillLight = new THREE.DirectionalLight(0xe0f2fe, 0.45);\n            fillLight.position.set(-6, 2, -3);\n            scene.add(fillLight);\n\n            buildDongmyoStreet();\n            setupEventListeners();\n            animate();\n        }\n\n        /* -------------------------------------------------------------------------\n           오픈 프론트 부스 방식의 파스텔 레트로 가게 및 외관 정체성 프롭 조립\n           ------------------------------------------------------------------------- */\n        function buildDongmyoStreet() {\n            const roadMat = new THREE.MeshStandardMaterial({ color: 0xe7e5e4, roughness: 0.8 });\n            const road = new THREE.Mesh(new THREE.BoxGeometry(32, 0.1, 8), roadMat);\n            road.position.set(0, -0.05, 1);\n            road.receiveShadow = true;\n            scene.add(road);\n\n            storeClickMeshes = [];\n            interactiveItems = [];\n\n            // =========================================================================\n            // STORE 0: 👕 동묘 구제 옷집 (x = -6.8) - 파스텔 핑크/코랄\n            // =========================================================================\n            const store0 = new THREE.Group();\n            store0.position.set(storeXPositions[0], 0, 0);\n\n            const wallMat0 = new THREE.MeshStandardMaterial({ color: 0xffa0a0, roughness: 0.4 });\n            const backWall0 = new THREE.Mesh(new THREE.BoxGeometry(4.4, 3.4, 0.2), wallMat0);\n            backWall0.position.set(0, 1.7, -1.2);\n            const sideWall0L = new THREE.Mesh(new THREE.BoxGeometry(0.2, 3.4, 2.4), wallMat0);\n            sideWall0L.position.set(-2.1, 1.7, 0);\n            const sideWall0R = sideWall0L.clone();\n            sideWall0R.position.x = 2.1;\n            \n            store0.add(backWall0, sideWall0L, sideWall0R);\n\n            const awning0 = new THREE.Mesh(new THREE.BoxGeometry(4.6, 0.22, 0.8), new THREE.MeshStandardMaterial({ color: 0xff4d4d, roughness: 0.3 }));\n            awning0.position.set(0, 3.2, 0.4);\n            awning0.rotateX(0.2);\n            store0.add(awning0);\n\n            createStoreSign(store0, \"👕 동묘 구제 옷집\", 0, 3.8, 0.4);\n\n            // [외관 정체성 1] 가게 앞 옷걸이 행거 가대\n            const rackGroup = new THREE.Group();\n            const pipeMat = new THREE.MeshStandardMaterial({ color: 0x18181b, metalness: 0.8 });\n            const pL = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 1.3), pipeMat);\n            pL.position.set(-1.4, 0.65, 1.2);\n            const pR = pL.clone();\n            pR.position.x = -0.6;\n            const pBar = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 0.85), pipeMat);\n            pBar.rotateZ(Math.PI / 2);\n            pBar.position.set(-1.0, 1.28, 1.2);\n            rackGroup.add(pL, pR, pBar);\n\n            const hangCloth1 = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.65, 0.08), new THREE.MeshStandardMaterial({ color: 0x2563eb }));\n            hangCloth1.position.set(-1.15, 0.9, 1.2);\n            const hangCloth2 = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.65, 0.08), new THREE.MeshStandardMaterial({ color: 0xf59e0b }));\n            hangCloth2.position.set(-0.85, 0.9, 1.2);\n            rackGroup.add(hangCloth1, hangCloth2);\n            store0.add(rackGroup);\n\n            // [외관 정체성 2] 마네킹\n            const mannequin = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.12, 0.85, 16), new THREE.MeshStandardMaterial({ color: 0x10b981 }));\n            mannequin.position.set(1.2, 0.6, 1.2);\n            store0.add(mannequin);\n\n            // --- 가게 내부 진열대 및 3D 보물 ---\n            const counter0 = new THREE.Mesh(new THREE.BoxGeometry(2.8, 0.5, 0.9), new THREE.MeshStandardMaterial({ color: 0xffe4e6, roughness: 0.3 }));\n            counter0.position.set(0, 0.25, 0.0);\n            store0.add(counter0);\n\n            // 3D 보물 1: 가죽 재킷\n            const jacketGroup = createDetailedJacket();\n            jacketGroup.position.set(-0.65, 0.8, 0.0);\n            store0.add(jacketGroup);\n            const tag1 = createPriceTag(jacketGroup, \"80s 가죽재킷\", \"12,000원\");\n\n            interactiveItems.push({\n                group: jacketGroup, tagSprite: tag1, id: 1, storeIndex: 0, name: \"80s 가죽재킷\", origPrice: 15000, price: 12000, icon: \"🧥\",\n                isBought: false, origPos: new THREE.Vector3(-0.65, 0.8, 0.0)\n            });\n\n            // 3D 보물 2: Y2K 바람막이\n            const windbreakerGroup = createDetailedWindbreaker();\n            windbreakerGroup.position.set(0.65, 0.8, 0.0);\n            store0.add(windbreakerGroup);\n            const tag2 = createPriceTag(windbreakerGroup, \"Y2K 바람막이\", \"8,000원\");\n\n            interactiveItems.push({\n                group: windbreakerGroup, tagSprite: tag2, id: 2, storeIndex: 0, name: \"Y2K 바람막이\", origPrice: 10000, price: 8000, icon: \"🥼\",\n                isBought: false, origPos: new THREE.Vector3(0.65, 0.8, 0.0)\n            });\n\n            scene.add(store0);\n            backWall0.userData = { storeIndex: 0 };\n            storeClickMeshes.push(backWall0);\n\n            // =========================================================================\n            // STORE 1: 📻 레트로 전자 상회 (x = 0.0) - 파스텔 민트/시안\n            // =========================================================================\n            const store1 = new THREE.Group();\n            store1.position.set(storeXPositions[1], 0, 0);\n\n            const wallMat1 = new THREE.MeshStandardMaterial({ color: 0x5eead4, roughness: 0.3 });\n            const backWall1 = new THREE.Mesh(new THREE.BoxGeometry(4.4, 3.4, 0.2), wallMat1);\n            backWall1.position.set(0, 1.7, -1.2);\n            const sideWall1L = new THREE.Mesh(new THREE.BoxGeometry(0.2, 3.4, 2.4), wallMat1);\n            sideWall1L.position.set(-2.1, 1.7, 0);\n            const sideWall1R = sideWall1L.clone();\n            sideWall1R.position.x = 2.1;\n            \n            store1.add(backWall1, sideWall1L, sideWall1R);\n\n            const awning1 = new THREE.Mesh(new THREE.BoxGeometry(4.6, 0.22, 0.8), new THREE.MeshStandardMaterial({ color: 0x0284c7, roughness: 0.3 }));\n            awning1.position.set(0, 3.2, 0.4);\n            awning1.rotateX(0.2);\n            store1.add(awning1);\n\n            createStoreSign(store1, \"📻 레트로 전자 상회\", 0, 3.8, 0.4);\n\n            // [외관 정체성] CRT 레트로 TV 스피커 탑\n            const tvMat = new THREE.MeshStandardMaterial({ color: 0x3f3f46, roughness: 0.4 });\n            const tvScreenMat = new THREE.MeshPhysicalMaterial({ color: 0x38bdf8, roughness: 0.1, clearcoat: 0.9, emissive: 0x0284c7, emissiveIntensity: 0.2 });\n            \n            const tv1 = new THREE.Mesh(new THREE.BoxGeometry(0.65, 0.52, 0.5), tvMat);\n            tv1.position.set(-1.3, 0.26, 1.2);\n            const scr1 = new THREE.Mesh(new THREE.BoxGeometry(0.48, 0.38, 0.02), tvScreenMat);\n            scr1.position.set(-1.3, 0.26, 1.46);\n\n            const tv2 = new THREE.Mesh(new THREE.BoxGeometry(0.52, 0.42, 0.45), tvMat);\n            tv2.position.set(-1.3, 0.73, 1.2);\n            const scr2 = new THREE.Mesh(new THREE.BoxGeometry(0.38, 0.3, 0.02), tvScreenMat);\n            scr2.position.set(-1.3, 0.73, 1.43);\n\n            store1.add(tv1, scr1, tv2, scr2);\n\n            // --- 가게 내부 진열대 및 3D 보물 ---\n            const counter1 = new THREE.Mesh(new THREE.BoxGeometry(2.8, 0.5, 0.9), new THREE.MeshStandardMaterial({ color: 0xccfbf1, roughness: 0.3 }));\n            counter1.position.set(0, 0.25, 0.0);\n            store1.add(counter1);\n\n            // 3D 보물 3: Y2K 디카\n            const cameraGroup = createDetailedCamera();\n            cameraGroup.position.set(-0.65, 0.7, 0.0);\n            store1.add(cameraGroup);\n            const tag3 = createPriceTag(cameraGroup, \"Y2K 컴팩트디카\", \"18,000원\");\n\n            interactiveItems.push({\n                group: cameraGroup, tagSprite: tag3, id: 3, storeIndex: 1, name: \"Y2K 컴팩트디카\", origPrice: 22000, price: 18000, icon: \"📷\",\n                isBought: false, origPos: new THREE.Vector3(-0.65, 0.7, 0.0)\n            });\n\n            // 3D 보물 4: 레트로 붐박스\n            const boomboxGroup = createDetailedBoombox();\n            boomboxGroup.position.set(0.65, 0.75, 0.0);\n            store1.add(boomboxGroup);\n            const tag4 = createPriceTag(boomboxGroup, \"레트로 붐박스\", \"15,000원\");\n\n            interactiveItems.push({\n                group: boomboxGroup, tagSprite: tag4, id: 4, storeIndex: 1, name: \"레트로 붐박스\", origPrice: 19000, price: 15000, icon: \"📻\",\n                isBought: false, origPos: new THREE.Vector3(0.65, 0.75, 0.0)\n            });\n\n            scene.add(store1);\n            backWall1.userData = { storeIndex: 1 };\n            storeClickMeshes.push(backWall1);\n\n            // =========================================================================\n            // STORE 2: 👓 동묘 골동품 만물상 (x = 6.8) - 버터 옐로우/바닐라\n            // =========================================================================\n            const store2 = new THREE.Group();\n            store2.position.set(storeXPositions[2], 0, 0);\n\n            const wallMat2 = new THREE.MeshStandardMaterial({ color: 0xfde047, roughness: 0.4 });\n            const backWall2 = new THREE.Mesh(new THREE.BoxGeometry(4.4, 3.4, 0.2), wallMat2);\n            backWall2.position.set(0, 1.7, -1.2);\n            const sideWall2L = new THREE.Mesh(new THREE.BoxGeometry(0.2, 3.4, 2.4), wallMat2);\n            sideWall2L.position.set(-2.1, 1.7, 0);\n            const sideWall2R = sideWall2L.clone();\n            sideWall2R.position.x = 2.1;\n            \n            store2.add(backWall2, sideWall2L, sideWall2R);\n\n            const awning2 = new THREE.Mesh(new THREE.BoxGeometry(4.6, 0.22, 0.8), new THREE.MeshStandardMaterial({ color: 0xd97706, roughness: 0.3 }));\n            awning2.position.set(0, 3.2, 0.4);\n            awning2.rotateX(0.2);\n            store2.add(awning2);\n\n            createStoreSign(store2, \"👓 골동품 만물상\", 0, 3.8, 0.4);\n\n            // [외관 정체성] 대형 앤티크 괘종시계\n            const clockFrame = new THREE.Mesh(new THREE.BoxGeometry(0.65, 1.1, 0.15), new THREE.MeshStandardMaterial({ color: 0x78350f, roughness: 0.5 }));\n            clockFrame.position.set(1.3, 1.6, 1.2);\n            const clockFace = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.22, 0.04, 24), new THREE.MeshStandardMaterial({ color: 0xfff0bb }));\n            clockFace.rotateX(Math.PI / 2);\n            clockFace.position.set(1.3, 1.8, 1.28);\n            store2.add(clockFrame, clockFace);\n\n            // --- 가게 내부 진열대 및 3D 보물 ---\n            const counter2 = new THREE.Mesh(new THREE.BoxGeometry(2.8, 0.5, 0.9), new THREE.MeshStandardMaterial({ color: 0xfef9c3, roughness: 0.3 }));\n            counter2.position.set(0, 0.25, 0.0);\n            store2.add(counter2);\n\n            // 3D 보물 5: 틴트 선글라스\n            const glassGroup = createDetailedSunglasses();\n            glassGroup.position.set(-0.65, 0.65, 0.0);\n            store2.add(glassGroup);\n            const tag5 = createPriceTag(glassGroup, \"틴트 선글라스\", \"5,500원\");\n\n            interactiveItems.push({\n                group: glassGroup, tagSprite: tag5, id: 5, storeIndex: 2, name: \"틴트 선글라스\", origPrice: 7000, price: 5500, icon: \"🕶️\",\n                isBought: false, origPos: new THREE.Vector3(-0.65, 0.65, 0.0)\n            });\n\n            // 3D 보물 6: 태엽 시계\n            const watchGroup = createDetailedWatch();\n            watchGroup.position.set(0.65, 0.65, 0.0);\n            store2.add(watchGroup);\n            const tag6 = createPriceTag(watchGroup, \"태엽 손목시계\", \"11,000원\");\n\n            interactiveItems.push({\n                group: watchGroup, tagSprite: tag6, id: 6, storeIndex: 2, name: \"태엽 손목시계\", origPrice: 14000, price: 11000, icon: \"⌚\",\n                isBought: false, origPos: new THREE.Vector3(0.65, 0.65, 0.0)\n            });\n\n            scene.add(store2);\n            backWall2.userData = { storeIndex: 2 };\n            storeClickMeshes.push(backWall2);\n\n            updateItemsVisibility();\n        }\n\n        /* -------------------------------------------------------------------------\n           상품 세부 디테일 3D 생성 함수들\n           ------------------------------------------------------------------------- */\n        function createDetailedJacket() {\n            const group = new THREE.Group();\n            const leatherMat = new THREE.MeshPhysicalMaterial({ color: 0x18181b, roughness: 0.2, clearcoat: 0.8 });\n            \n            const body = new THREE.Mesh(new THREE.BoxGeometry(0.65, 0.75, 0.22), leatherMat);\n            const collarL = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.15, 0.05), leatherMat);\n            collarL.position.set(-0.15, 0.32, 0.12);\n            collarL.rotateZ(-0.2);\n            const collarR = collarL.clone();\n            collarR.position.x = 0.15;\n            collarR.rotateZ(0.4);\n\n            const armL = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.65, 0.18), leatherMat);\n            armL.position.set(-0.38, -0.05, 0);\n            const armR = armL.clone();\n            armR.position.x = 0.38;\n\n            const zipper = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.7, 0.02), new THREE.MeshStandardMaterial({ color: 0xd4af37, metalness: 0.9 }));\n            zipper.position.set(0, 0, 0.12);\n\n            group.add(body, collarL, collarR, armL, armR, zipper);\n            return group;\n        }\n\n        function createDetailedWindbreaker() {\n            const group = new THREE.Group();\n            const mat1 = new THREE.MeshStandardMaterial({ color: 0xec4899, roughness: 0.3 });\n            const mat2 = new THREE.MeshStandardMaterial({ color: 0x06b6d4, roughness: 0.3 });\n            const mat3 = new THREE.MeshStandardMaterial({ color: 0xeab308, roughness: 0.3 });\n\n            const upper = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.26, 0.2), mat1);\n            upper.position.y = 0.2;\n            const mid = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.26, 0.2), mat2);\n            mid.position.y = -0.04;\n            const lower = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.22, 0.2), mat3);\n            lower.position.y = -0.26;\n\n            const zipper = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.72, 0.02), new THREE.MeshStandardMaterial({ color: 0xffffff }));\n            zipper.position.set(0, -0.02, 0.11);\n\n            group.add(upper, mid, lower, zipper);\n            return group;\n        }\n\n        function createDetailedCamera() {\n            const group = new THREE.Group();\n            const camMat = new THREE.MeshStandardMaterial({ color: 0xe5e7eb, metalness: 0.9, roughness: 0.15 });\n            const body = new THREE.Mesh(new THREE.BoxGeometry(0.52, 0.34, 0.16), camMat);\n\n            const lensMat = new THREE.MeshPhysicalMaterial({ color: 0x111111, roughness: 0.1, clearcoat: 1.0 });\n            const lensRing1 = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.13, 0.06, 24), camMat);\n            lensRing1.rotateX(Math.PI / 2);\n            lensRing1.position.set(0.08, 0, 0.1);\n            const lensGlass = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.1, 0.08, 24), lensMat);\n            lensGlass.rotateX(Math.PI / 2);\n            lensGlass.position.set(0.08, 0, 0.12);\n\n            const flash = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.07, 0.04), new THREE.MeshStandardMaterial({ color: 0xfff0bb }));\n            flash.position.set(-0.16, 0.1, 0.09);\n\n            group.add(body, lensRing1, lensGlass, flash);\n            return group;\n        }\n\n        function createDetailedBoombox() {\n            const group = new THREE.Group();\n            const bbMat = new THREE.MeshStandardMaterial({ color: 0x27272a, roughness: 0.3 });\n            const body = new THREE.Mesh(new THREE.BoxGeometry(0.85, 0.42, 0.28), bbMat);\n\n            const spkMat = new THREE.MeshStandardMaterial({ color: 0xef4444, roughness: 0.5 });\n            const spkL = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.14, 0.04, 20), spkMat);\n            spkL.rotateX(Math.PI / 2);\n            spkL.position.set(-0.25, 0, 0.13);\n            const spkR = spkL.clone();\n            spkR.position.x = 0.25;\n\n            const handle = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.06, 0.06), bbMat);\n            handle.position.set(0, 0.26, 0);\n\n            group.add(body, spkL, spkR, handle);\n            return group;\n        }\n\n        function createDetailedSunglasses() {\n            const group = new THREE.Group();\n            const goldMat = new THREE.MeshStandardMaterial({ color: 0xd4af37, metalness: 0.9, roughness: 0.2 });\n            const lensMat = new THREE.MeshPhysicalMaterial({ color: 0xf59e0b, transmission: 0.85, transparent: true, roughness: 0.1 });\n\n            const rimL = new THREE.Mesh(new THREE.TorusGeometry(0.11, 0.018, 12, 24), goldMat);\n            rimL.position.x = -0.13;\n            const rimR = rimL.clone();\n            rimR.position.x = 0.13;\n\n            const lensL = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.1, 0.015, 20), lensMat);\n            lensL.rotateX(Math.PI / 2);\n            lensL.position.x = -0.13;\n            const lensR = lensL.clone();\n            lensR.position.x = 0.13;\n\n            group.add(rimL, rimR, lensL, lensR);\n            return group;\n        }\n\n        function createDetailedWatch() {\n            const group = new THREE.Group();\n            const goldMat = new THREE.MeshStandardMaterial({ color: 0xd4af37, metalness: 0.9, roughness: 0.2 });\n            \n            const wCase = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.15, 0.05, 24), goldMat);\n            const wGlass = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.14, 0.02, 24), new THREE.MeshPhysicalMaterial({ color: 0xffffff, transmission: 0.9, transparent: true }));\n            wGlass.position.y = 0.03;\n\n            const strapMat = new THREE.MeshStandardMaterial({ color: 0x78350f, roughness: 0.6 });\n            const strap1 = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.02, 0.32), strapMat);\n            strap1.position.z = 0.2;\n            const strap2 = strap1.clone();\n            strap2.position.z = -0.2;\n\n            group.add(wCase, wGlass, strap1, strap2);\n            return group;\n        }\n\n        /* 고해상도 A2Z 간판 스프라이트 */\n        function createStoreSign(parentGroup, text, x, y, z) {\n            const canvas = document.createElement('canvas');\n            canvas.width = 1024;\n            canvas.height = 256;\n            const ctx = canvas.getContext('2d');\n\n            ctx.fillStyle = '#FEFEFE';\n            ctx.roundRect(16, 16, 992, 224, 112);\n            ctx.fill();\n            ctx.lineWidth = 16;\n            ctx.strokeStyle = '#1C1C20';\n            ctx.stroke();\n\n            ctx.fillStyle = '#1C1C20';\n            ctx.font = 'bold 84px SUIT, sans-serif';\n            ctx.textAlign = 'center';\n            ctx.textBaseline = 'middle';\n            ctx.fillText(text, 512, 128);\n\n            const texture = new THREE.CanvasTexture(canvas);\n            const spriteMat = new THREE.SpriteMaterial({ map: texture, depthTest: false });\n            const sprite = new THREE.Sprite(spriteMat);\n            sprite.scale.set(3.0, 0.75, 1);\n            sprite.position.set(x, y, z);\n            parentGroup.add(sprite);\n        }\n\n        /* 3D 보물 가격 태그 (최우선 렌더링 설정 적용) */\n        function createPriceTag(parentGroup, title, priceText) {\n            const canvas = document.createElement('canvas');\n            canvas.width = 512;\n            canvas.height = 256;\n            const ctx = canvas.getContext('2d');\n\n            ctx.fillStyle = '#1C1C20';\n            ctx.roundRect(10, 10, 492, 236, 40);\n            ctx.fill();\n            ctx.lineWidth = 12;\n            ctx.strokeStyle = '#FEFEFE';\n            ctx.stroke();\n\n            ctx.fillStyle = '#FEFEFE';\n            ctx.font = 'bold 48px SUIT, sans-serif';\n            ctx.textAlign = 'center';\n            ctx.fillText(title, 256, 90);\n\n            ctx.fillStyle = '#FFD600';\n            ctx.font = 'black 54px SUIT, sans-serif';\n            ctx.fillText(priceText, 256, 175);\n\n            const texture = new THREE.CanvasTexture(canvas);\n            const spriteMat = new THREE.SpriteMaterial({ map: texture, depthTest: false, renderOrder: 999 });\n            const sprite = new THREE.Sprite(spriteMat);\n            sprite.scale.set(0.68, 0.34, 1);\n            sprite.position.set(0, 0.42, 0);\n            parentGroup.add(sprite);\n            return sprite;\n        }\n\n        /* 득템 후 가격표 텍스트 업데이트 (✨ 득템 완료!) */\n        function updatePriceTagBought(sprite, title) {\n            const canvas = document.createElement('canvas');\n            canvas.width = 512;\n            canvas.height = 256;\n            const ctx = canvas.getContext('2d');\n\n            ctx.fillStyle = '#1C1C20';\n            ctx.roundRect(10, 10, 492, 236, 40);\n            ctx.fill();\n            ctx.lineWidth = 12;\n            ctx.strokeStyle = '#22c55e';\n            ctx.stroke();\n\n            ctx.fillStyle = '#FEFEFE';\n            ctx.font = 'bold 44px SUIT, sans-serif';\n            ctx.textAlign = 'center';\n            ctx.fillText(title, 256, 90);\n\n            ctx.fillStyle = '#4ade80';\n            ctx.font = 'black 52px SUIT, sans-serif';\n            ctx.fillText('✨ 득템 완료!', 256, 175);\n\n            sprite.material.map = new THREE.CanvasTexture(canvas);\n            sprite.material.map.needsUpdate = true;\n        }\n\n        /* 뷰 상태별 3D 보물 아이템 노출 제어 */\n        function updateItemsVisibility() {\n            interactiveItems.forEach(item => {\n                if (currentState === 'STORE' && item.storeIndex === currentStoreIndex) {\n                    item.group.visible = true;\n                    item.tagSprite.visible = true;\n                } else {\n                    item.group.visible = false;\n                    item.tagSprite.visible = false;\n                }\n            });\n        }\n\n        /* =========================================================================\n           3. 카메라 스무스 이동 및 상태 전환 (거리 뷰 ↔ 진열대 뷰)\n           ========================================================================= */\n        function enterStore(index) {\n            soundEngine.playEnter();\n            currentState = 'STORE';\n            currentStoreIndex = index;\n\n            const targetX = storeXPositions[index];\n            targetCamPos.set(targetX, 1.2, 3.6);  // 여유로운 줌인 거리 확보\n            targetLookAt.set(targetX, 0.7, 0.0);\n\n            updateItemsVisibility();\n\n            // UI 제어\n            document.getElementById('scroll-guide-tip').classList.add('opacity-0');\n            document.getElementById('store-back-bar').classList.remove('hidden');\n\n            const names = ['👕 동묘 구제 옷집', '📻 동묘 레트로 전자 상회', '👓 동묘 골동품 만물상'];\n            document.getElementById('store-title-text').innerText = `◀ ${names[index]}에서 나가기`;\n        }\n\n        function exitStore() {\n            currentState = 'STREET';\n            currentStoreIndex = -1;\n\n            targetCamPos.set(streetCamX, 2.8, 9.8);\n            targetLookAt.set(streetCamX, 1.4, 0);\n\n            updateItemsVisibility();\n\n            // UI 제어\n            document.getElementById('scroll-guide-tip').classList.remove('opacity-0');\n            document.getElementById('store-back-bar').classList.add('hidden');\n        }\n\n        /* =========================================================================\n           4. 마우스 & 터치 드래그 스크롤 & 터치 득템 인터랙션\n           ========================================================================= */\n        function setupEventListeners() {\n            const canvas = document.getElementById('webgl-canvas');\n            document.addEventListener('contextmenu', e => e.preventDefault());\n\n            canvas.addEventListener('pointerdown', onPointerDown);\n            canvas.addEventListener('pointermove', onPointerMove);\n            canvas.addEventListener('pointerup', onPointerUp);\n\n            window.addEventListener('resize', onWindowResize);\n        }\n\n        function updateMouseCoords(e) {\n            mouse.x = (e.clientX / window.innerWidth) * 2 - 1;\n            mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;\n        }\n\n        function onPointerDown(e) {\n            isDragging = true;\n            dragStartX = e.clientX;\n            dragStartCamX = streetCamX;\n            totalDragDistance = 0;\n            updateMouseCoords(e);\n        }\n\n        function onPointerMove(e) {\n            if (!isDragging) return;\n\n            const deltaX = e.clientX - dragStartX;\n            totalDragDistance += Math.abs(deltaX);\n\n            if (currentState === 'STREET') {\n                // 거리 뷰에서 드래그 스크롤 (X축 범위 -7.8 ~ +7.8)\n                streetCamX = dragStartCamX - deltaX * 0.009;\n                streetCamX = Math.max(-7.8, Math.min(7.8, streetCamX));\n\n                targetCamPos.x = streetCamX;\n                targetLookAt.x = streetCamX;\n            }\n        }\n\n        function onPointerUp(e) {\n            isDragging = false;\n            updateMouseCoords(e);\n\n            // 단순 클릭 시 (드래그 미발생)\n            if (totalDragDistance < 8) {\n                raycaster.setFromCamera(mouse, camera);\n\n                if (currentState === 'STREET') {\n                    // 거리 뷰: 가게 클릭 시 해당 가게로 입장\n                    const intersects = raycaster.intersectObjects(storeClickMeshes, true);\n                    if (intersects.length > 0) {\n                        const hitObj = intersects[0].object;\n                        if (hitObj.userData.storeIndex !== undefined) {\n                            enterStore(hitObj.userData.storeIndex);\n                        }\n                    }\n                } else if (currentState === 'STORE') {\n                    // 가게 내부 뷰: 3D 보물 아이템 클릭 시 득템\n                    for (let i = 0; i < interactiveItems.length; i++) {\n                        const item = interactiveItems[i];\n                        if (item.storeIndex !== currentStoreIndex) continue;\n\n                        const intersects = raycaster.intersectObject(item.group, true);\n                        if (intersects.length > 0) {\n                            if (!item.isBought) {\n                                if (budget < item.price) {\n                                    alert('지갑 잔액이 부족합니다!');\n                                    return;\n                                }\n\n                                item.isBought = true;\n                                boughtItems.push(item);\n                                budget -= item.price;\n\n                                updatePriceTagBought(item.tagSprite, item.name);\n\n                                soundEngine.playBuy();\n                                updateHUD();\n                            }\n                            break;\n                        }\n                    }\n                }\n            }\n        }\n\n        function updateHUD() {\n            document.getElementById('hud-budget').innerText = `${budget.toLocaleString()}원`;\n            document.getElementById('hud-count').innerText = `${boughtItems.length}개`;\n        }\n\n        /* -------------------------------------------------------------------------\n           3D 물리 및 카메라 보간 프레임 업데이트\n           ------------------------------------------------------------------------- */\n        function updatePhysics() {\n            camera.position.lerp(targetCamPos, 0.08);\n            currentLookAt.lerp(targetLookAt, 0.08);\n            camera.lookAt(currentLookAt);\n\n            // 득템한 3D 오브젝트 공중 부양 회전 애니메이션\n            interactiveItems.forEach(item => {\n                if (item.isBought) {\n                    const targetY = item.origPos.y + 0.25;\n                    item.group.position.y += (targetY - item.group.position.y) * 0.1;\n                    item.group.rotation.y += 0.03;\n                }\n            });\n        }\n\n        function animate() {\n            requestAnimationFrame(animate);\n            updatePhysics();\n            renderer.render(scene, camera);\n        }\n\n        function onWindowResize() {\n            camera.aspect = window.innerWidth / window.innerHeight;\n            camera.updateProjectionMatrix();\n            renderer.setSize(window.innerWidth, window.innerHeight);\n        }\n\n        /* =========================================================================\n           5. 영수증 출력 모달\n           ========================================================================= */\n        function toggleReceipt() {\n            if (boughtItems.length === 0) {\n                alert('동묘 상점에 입장해 마음에 드는 3D 보물을 클릭해 득템해보세요!');\n                return;\n            }\n\n            const modal = document.getElementById('receipt-modal');\n            const isHidden = modal.classList.contains('hidden');\n\n            if (isHidden) {\n                soundEngine.playReceipt();\n                renderReceiptList();\n                modal.classList.remove('hidden');\n            } else {\n                modal.classList.add('hidden');\n            }\n        }\n\n        function renderReceiptList() {\n            const container = document.getElementById('receipt-items-list');\n            container.innerHTML = '';\n\n            let totalSpent = 0;\n            let totalSaved = 0;\n\n            boughtItems.forEach(item => {\n                totalSpent += item.price;\n                const saved = item.origPrice - item.price;\n                totalSaved += saved;\n\n                const row = document.createElement('div');\n                row.className = 'flex justify-between items-center';\n                row.innerHTML = `\n                    <span>${item.icon} ${item.name}</span>\n                    <span class=\"font-bold\">${item.price.toLocaleString()}원</span>\n                `;\n                container.appendChild(row);\n            });\n\n            document.getElementById('receipt-total').innerText = `${totalSpent.toLocaleString()}원`;\n            document.getElementById('receipt-saved').innerText = `-${totalSaved.toLocaleString()}원`;\n            document.getElementById('receipt-balance').innerText = `${budget.toLocaleString()}원`;\n\n            const badge = document.getElementById('receipt-badge');\n            if (totalSaved >= 4000) {\n                badge.innerText = '\"동묘 협상의 신 (네고 마스터)\"';\n            } else if (totalSpent >= 25000) {\n                badge.innerText = '\"동묘 힙스터 트렌드세터\"';\n            } else {\n                badge.innerText = '\"알뜰한 레트로 수집가\"';\n            }\n        }\n\n        function resetShopping() {\n            budget = INITIAL_BUDGET;\n            boughtItems = [];\n\n            interactiveItems.forEach(item => {\n                item.isBought = false;\n                item.group.position.copy(item.origPos);\n                item.group.rotation.y = 0;\n                \n                // 가격 태그 재설정\n                createPriceTag(item.group, item.name, `${item.price.toLocaleString()}원`);\n            });\n\n            document.getElementById('receipt-modal').classList.add('hidden');\n            exitStore();\n            updateHUD();\n        }\n\n        window.onload = function() {\n            init3D();\n        };\n    <\/script>\n</body>\n</html>"};
